INSERT INTO `about_ceo` (`id`, `name`, `about`, `fileName`, `added_date`) VALUES
(55, 'মোঃ আবু তাহের চৌধুরী', '<h4 style=\"text-align: center;\"><u><strong>ব্যক্তিগত</strong> <strong>তথ্য</strong></u></h4>\r\n\r\n<p style=\"text-align: justify;\">বাংলাদেশ সিভিল সার্ভিস ৯ম ব্যাচের সমবায় ক্যাডারের&nbsp;সদস্য মোঃ আবু তাহের চৌধুরী ০১ জুলাই, ২০২১&nbsp;তারিখে ব্যবস্থাপনা পরিচালক ও প্রধান নির্বাহী অফিসার হিসেবে যোগদান করেন। তিনি ৩০ বছরের বেশী সময় সরকারি ও বেসরকারি বিভিন্ন প্রতিষ্ঠানে নির্বাহী হিসেবে কাজ করেন। তিনি সমবায় অধিদপ্তরের মাঠ পর্যায়ের একাধিক বিভাগসহ প্রধান কার্যালয়ের বিভিন্ন বিভাগের&nbsp;প্রধান&nbsp;হিসেবে দায়িত্ব পালন করেন।এছাড়াও&nbsp;তিনি প্রেষনে বাংলাদেশ সমবায় ব্যাংক লিঃ এর মানব সম্পদ বিভাগের প্রধান এবং বাংলাদেশ ন্যাশনাল ফিসারম্যান কোঅপারেটিভ সোসাইটি লিঃ এর জেনারেল ম্যনেজার ও সিইও হিসেবে দায়িত্ব পালন করেছেন।&nbsp;<br />\r\nতিনি ঢাকা বিশ্ববিদ্যালয় হতে ফিনান্স-এ অনার্সসহ ব্যাচেলর এবং ব্যাংকিং মেজরসহ এমবিএ সম্পন্ন করেছেন। তিনি বাংলাদেশ লোকপ্রশাসন প্রশিক্ষণ কেন্দ্র, পরিকল্পনা ও উন্নয়ন একাডেমী, ফিনান্সিয়াল ম্যানেজমেন্ট একাডেমী, বাংলাদেশ ব্যাংক ট্রেনিং একাডেমী, বাংলাদেশ সমবায় একাডেমী, বাংলাদেশ পল্লী উন্নয়ন একাডেমীসহ মার্কিন যুক্তরাষ্ট্র, কানাডা, জাপান, দঃ কোরিয়া, থাইল্যান্ড, মালয়েশিয়া, ইন্দোনেশিয়া, ভারত, শ্রীলংকা ও নেপাল হতে আইন, জন প্রশাসন, আর্থিক ব্যবস্থাপনা, প্রকল্প ব্যবস্থাপনা, সমবায় ব্যবস্থাপনা, মাইক্রো ফাইনান্স ব্যবস্থাপনা, ক্রেডিট ইউনিয়ন ব্যবস্থাপনাসহ বিভিন্ন বিষয়ে উচ্চতর পেশাগত প্রশিক্ষণ কোর্স&nbsp; সম্পন্ন করেছেন।<br />\r\nতিনি বাংলাদেশ সিভিল সার্ভিস ৯ম ব্যাচ ফোরাম ও বিসিএস (সমবায়) এসোসিয়েশনের মহাসচিব হিসেবে একাধিক বার দায়িত্ব পালন করেন। তিনি অফিসার্স ক্লাব ঢাকা, আর্মি গলফ ক্লাব, কুমিল্লা ক্লাবসহ বিভিন্ন&nbsp; পেশাজীবি ও সামাজিক সংগঠনের সাথে সম্পৃক্ত।তিনি বিবাহিত ও দু&rsquo;সন্তানের জনক।</p>\r\n\r\n<p>&nbsp;</p>', '', '2022-08-22 05:00:26');
INSERT INTO `about_secr` (`id`, `name`, `about`, `fileName`, `added_date`) VALUES
(35, 'দেবব্রত সরকার', '<p><strong>ব্যক্তিগত</strong> <strong>তথ্য</strong></p>\r\n\r\n<table align=\"center\" border=\"2\" cellpadding=\"0\" cellspacing=\"0\">\r\n <tbody>\r\n  <tr>\r\n   <td>\r\n   <p><strong>নাম</strong><strong>: দেবব্রত সরকার</strong></p>\r\n   </td>\r\n   <td>\r\n   <p><strong>পদবী</strong><strong>:</strong> সম্পাদক</p>\r\n   </td>\r\n  </tr>\r\n  <tr>\r\n   <td>\r\n   <p><strong>জন্ম</strong> <strong>তারিখ</strong><strong>:</strong> ০১ জানুয়ারী</p>\r\n   </td>\r\n   <td>\r\n   <p><strong>ন্যাশনাল</strong> <strong>আইডি</strong> <strong>কার্ড</strong><strong>:</strong> </p>\r\n   </td>\r\n  </tr>\r\n  <tr>\r\n   <td>\r\n   <p><strong>ধর্ম</strong><strong> :</strong> সনাতন ধর্ম</p>\r\n   </td>\r\n   <td>\r\n   <p><strong>পিতার</strong> <strong>নাম: </strong>নিখিল নারায়ন সরকার</p>\r\n   </td>\r\n  </tr>\r\n  <tr>\r\n   <td>\r\n   <p><strong>মাতার</strong> <strong>নাম: </strong>নির্মলা রানী সরকার</p>\r\n   </td>\r\n   <td>\r\n   <p><strong>বৈবাহিক</strong> <strong>অবস্থা</strong><strong>: </strong>বিবাহিত</p>\r\n   </td>\r\n  </tr>\r\n  <tr>\r\n   <td>\r\n   <p><strong>স্থায়ী</strong> <strong>ঠিকানা</strong>: শীল বাড়ী, গ্রাম-খাড়খাদিয়া, ডাকঘর-চান্দ্রা-৩৬৫১, উপজেলা-ফরিদগন্জ , জেলা: চাঁদপুর ।</p>\r\n   </td>\r\n   <td>\r\n   <p><strong>বর্তমান</strong> <strong>ঠিকানা:</strong> শীল বাড়ী, গ্রাম-খাড়খাদিয়া, ডাকঘর-চান্দ্রা-৩৬৫১,উপজেলা-ফরিদগন্জ , জেলা: চাঁদপুর ।</p>\r\n   </td>\r\n  </tr>\r\n  <tr>\r\n   <td>\r\n   <p><strong>মোবাইল :</strong></p>\r\n   </td>\r\n   <td>\r\n   <p>+৮৮০১০০০০০০০০০০</p>\r\n   </td>\r\n  </tr>\r\n  <tr>\r\n   <td>\r\n   <p><strong>ই-মেইল</strong></p>\r\n   </td>\r\n   <td>\r\n   <p><strong>sbc.cooperativesocietyltd@gmail.com</strong></p>\r\n   </td>\r\n  </tr>\r\n </tbody>\r\n</table>\r\n\r\n<p> </p>\r\n\r\n<p>                                                       </p>', '', '2022-08-02 10:39:27');
INSERT INTO `achievements` (`id`, `title`, `details`, `image`, `posted_by`, `created_at`, `status`) VALUES
(1, 'পাবনার দুগ্ধ খামারি', 'সম্মিলিত প্রচেষ্টায় দুধের ন্যায্যমূল্য নিশ্চিত করে খামারিদের আয় ৪০% বৃদ্ধি পেয়েছে।', '1775281471_image_35502_1587878716.jpg', 'Admin', '2026-04-04 04:13:22', 1),
(2, 'সাভারের নারী উদ্যোক্তা', 'ক্ষুদ্র ঋণের মাধ্যমে ২০ জন নারী এখন বুটিক ও হস্তশিল্পে স্বাবলম্বী।', '1775281491_image-35886-1520496471.jpg', 'Admin', '2026-04-04 04:13:22', 1),
(3, 'বগুড়ার সবজি চাষি', 'সরাসরি বাজারজাতকরণের মাধ্যমে মধ্যস্বত্বভোগীদের ছাড়াই দ্বিগুণ লাভ করছেন কৃষকরা।', '1775281508_0fe62d779d61e044bbc8d46072ff9c2212bbf7872233d32a.jpg', 'Admin', '2026-04-04 04:13:22', 1),
(4, 'বরিশালের মৎস্যজীবী সমবায়', 'আধুনিক জাল ও উন্নত নৌকার সহায়তায় ইলিশ আহরণে রেকর্ড সাফল্য অর্জন।', '1775281568_fish.jpg', 'Admin', '2026-04-04 04:13:22', 1),
(5, 'রংপুরের তাঁত শিল্প', 'শতরঞ্জি ও তাঁত পণ্য বিদেশে রপ্তানি করে শতভাগ ঋণ পরিশোধের অনন্য দৃষ্টান্ত।', '1775281580_1643532369_tant.jpg', 'Admin', '2026-04-04 04:13:22', 1);
