INSERT INTO `job_homepage` (`h_id`, `h_company_name`, `h_company_address`, `h_company_mobile`, `h_company_email`, `h_welcome_title`, `h_welcome_description`, `h_welcome_long_description`, `h_job_title`, `h_job_description`, `h_registration_title`, `h_registration_description`, `h_login_title`, `h_login_details`, `h_application_title`, `h_application_description`, `h_application_long_description`, `h_faq_title`, `h_faq_description`, `h_faq_long_description`, `h_footer_description`, `h_fb_link`, `h_youtube_link`, `h_twitter_link`, `h_linkedin_link`, `h_logo`, `h_header_right_image`) VALUES
(1, 'শিক্ষিত বেকার কেন্দ্রীয় সঞ্চয় ও ঋণদান সমবায় সমিতি', 'ওয়্যারলেছ বাজার, চাঁদপুর সদর, চাঁদপুর', '০১৭১২-৫৮৮৩২১', 'sbc.cooperativesocietyltd@gmail.com', 'Welcome to eRecruitment System', 'For all online applications related to job opening of SBCL.', '<p style=\"text-align:justify\">It&#39;s not only our customers who can be sure of a warm welcome. You can, too. Do you consider yourself as a natural born leader? Are you looking for a challenging career with superb prospects for ownership and success? Then join SBCL.</p>\r\n\r\n<h6 style=\"text-align:justify\">SBCL &ndash; the &#39;Employer of Choice&#39;</h6>\r\n\r\n<p style=\"text-align:justify\">&#39;People First&#39; &ndash; that&#39;s the motto of SBCL. We are the investor in people. Our people re-sourcing policy is we look for the &#39;best fit&#39;. We don&#39;t offer them a job &ndash; rather, we shape their career.</p>\r\n\r\n<p style=\"text-align:justify\">SBCL is one of the most recognized and respected local service brands, delivering outstanding, innovative products and premier service to our customers. Our success is built on the team and individual achievements of our people. For the individuals who help us achieve it, the career potential is huge. The fact is that they can go as far as they want to. And that is why we have been able attract and recruit finest people in the country.</p>\r\n', 'Job Opening', 'SBCL is an equal opportunity employer and welcomes applications from both male and female candidates.', 'Registration', 'Please Register yourself with us...', 'Login', 'We will inculcate a high performance culture where we will work with fun and pride.', 'How to Apply', 'You can register yourself anytime at our e-recruitment system by filling our online application form.', '<p style=\"text-align:justify\">You can register yourself anytime at our e-recruitment system by filling our online application form. After successful registration, you will be given a Tracking Number which will enable you to apply for any advertised jobs or edit your Resume anytime.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p style=\"text-align:justify\">Instruction for Applicants</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&lt;div class=&quot;row&quot; style=&quot;box-sizing: border-box; display: flex; flex-wrap: wrap; margin-right: -7.5px; margin-left: -7.5px; color: rgb(33, 37, 41); font-family: &quot; source=&quot;&quot; sans=&quot;&quot; pro&quot;,=&quot;&quot; -apple-system,=&quot;&quot; blinkmacsystemfont,=&quot;&quot; &quot;segoe=&quot;&quot; ui&quot;,=&quot;&quot; roboto,=&quot;&quot; &quot;helvetica=&quot;&quot; neue&quot;,=&quot;&quot; arial,=&quot;&quot; sans-serif,=&quot;&quot; &quot;apple=&quot;&quot; color=&quot;&quot; emoji&quot;,=&quot;&quot; ui=&quot;&quot; symbol&quot;;=&quot;&quot; font-size:=&quot;&quot; 16px;=&quot;&quot; text-align:=&quot;&quot; justify;&quot;=&quot;&quot;&gt;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<div class=\"col-2\" style=\"box-sizing: border-box; position: relative; width: 125px; padding-right: 7.5px; padding-left: 7.5px; flex: 0 0 16.6667%; max-width: 16.6667%;\">\r\n<p>Step 1:</p>\r\n</div>\r\n\r\n<div class=\"col-10\" style=\"box-sizing: border-box; position: relative; width: 625px; padding-right: 7.5px; padding-left: 7.5px; flex: 0 0 83.3333%; max-width: 83.3333%;\">\r\n<p>From the advertised vacancies, select the particular position you want to apply for note that you can apply more than one job at the same time. If there is no vacancy available, you can still post your Resume by going to apply online to be considered for any suitable positions in the future.</p>\r\n</div>\r\n\r\n<div class=\"col-2\" style=\"box-sizing: border-box; position: relative; width: 125px; padding-right: 7.5px; padding-left: 7.5px; flex: 0 0 16.6667%; max-width: 16.6667%;\">\r\n<p>Step 2:</p>\r\n</div>\r\n\r\n<div class=\"col-10\" style=\"box-sizing: border-box; position: relative; width: 625px; padding-right: 7.5px; padding-left: 7.5px; flex: 0 0 83.3333%; max-width: 83.3333%;\">\r\n<p>Click at &quot;Registration&quot; to access the Application/Resume Form</p>\r\n</div>\r\n\r\n<div class=\"col-2\" style=\"box-sizing: border-box; position: relative; width: 125px; padding-right: 7.5px; padding-left: 7.5px; flex: 0 0 16.6667%; max-width: 16.6667%;\">\r\n<p>Step 3:</p>\r\n</div>\r\n\r\n<div class=\"col-10\" style=\"box-sizing: border-box; position: relative; width: 625px; padding-right: 7.5px; padding-left: 7.5px; flex: 0 0 83.3333%; max-width: 83.3333%;\">\r\n<p>The Application/Resume Form will open. Please read the instructions to complete the form carefully. You must fill the fields marked with a star (*), otherwise your application will not be submitted. You will be given alert messages if any information is missing or completed incorrectly. Please read carefully those alert messages and complete the relevant fields properly.</p>\r\n</div>\r\n\r\n<div class=\"col-2\" style=\"box-sizing: border-box; position: relative; width: 125px; padding-right: 7.5px; padding-left: 7.5px; flex: 0 0 16.6667%; max-width: 16.6667%;\">\r\n<p>Step 4:</p>\r\n</div>\r\n\r\n<div class=\"col-10\" style=\"box-sizing: border-box; position: relative; width: 625px; padding-right: 7.5px; padding-left: 7.5px; flex: 0 0 83.3333%; max-width: 83.3333%;\">\r\n<p>After completing all fields, submit the form by clicking the button &quot;Save &amp; Finish&quot;.</p>\r\n</div>\r\n\r\n<div class=\"col-2\" style=\"box-sizing: border-box; position: relative; width: 125px; padding-right: 7.5px; padding-left: 7.5px; flex: 0 0 16.6667%; max-width: 16.6667%;\">\r\n<p>Step 5:</p>\r\n</div>\r\n\r\n<div class=\"col-10\" style=\"box-sizing: border-box; position: relative; width: 625px; padding-right: 7.5px; padding-left: 7.5px; flex: 0 0 83.3333%; max-width: 83.3333%;\">\r\n<p>If your application has been successfully submitted you will be given a tracking number which you can use as a reference for editing/updating your resume at a later date or to Apply for a specific job vacancy offered in future.</p>\r\n</div>\r\n\r\n<div class=\"wrapper\" id=\"wrapper\" style=\"box-sizing: border-box; min-height: 100%; position: relative; color: rgb(33, 37, 41); font-family: \">\r\n<div class=\"container job_details\" style=\"box-sizing: border-box; width: 1140px; padding: 15px; margin-right: auto; margin-left: auto; max-width: 1140px; border-radius: 5px;\">\r\n<div class=\"row align-items-center\" style=\"box-sizing: border-box; display: flex; flex-wrap: wrap; margin-right: -7.5px; margin-left: -7.5px; align-items: center !important;\">\r\n<div class=\"col-4\" style=\"box-sizing: border-box; position: relative; width: 375px; padding-right: 7.5px; padding-left: 7.5px; flex: 0 0 33.3333%; max-width: 33.3333%;\">&nbsp;</div>\r\n</div>\r\n</div>\r\n</div>\r\n', 'FAQ', 'You can register yourself anytime at our e-recruitment system by filling our online application form.', '<h6 style=\"text-align:justify\">What is CV Bank?</h6>\r\n\r\n<p style=\"text-align:justify\">SBCL is preserving all online application from December, 2009. If you have applied for any post, published and receiving online application in SBCL website, then your CV is preserved in our CV Bank. And you are given a CV Identification Number. Using that number you can again apply for another post advertised in our site.</p>\r\n\r\n<h6 style=\"text-align:justify\">What is CV Identification Number or Job Tracking Number?</h6>\r\n\r\n<p style=\"text-align:justify\">CV Identification Number is a unique number given against a new CV posted online to SBCL eRecruitment. Using the CV Identification Number, an applicant can apply for different positions advertised in our site. Applicant needs not to create new CV for applying a new post, but use the CV Identification Number and password to edit current CV and apply for a new post. On the other hand, Job Tracking number is created against a post and a CV ID. An applicant will have only one CV ID, but he/she will have different Job Tracking Number for different posts.</p>\r\n', 'Lorem ipsum dolor sit amet, consectetur adipisicing elit. Nisi exercitationem iure facere perspiciatis accusantium harum ipsa, ab sapiente molestiae porro eos at ad. Nobis nesciunt, possimus ipsa porro aspernatur iure.', 'https://www.facebook.com/', 'https://www.youtube.com/', 'https://twitter.com/', 'https://www.linkedin.com/', '1656499904_logo.png', '1740294939_header_side_image.jpg');
