(8, 'দেবব্রত সরকার', '1662013149_filename.jpg', '০৭.০১.২০২১ ইং- চলমান', '৮ম', 'নির্বাচিত', '<table align=\"center\" border=\"1\" cellpadding=\"1\" cellspacing=\"1\" style=\"width:500px\">\r\n	<tbody>\r\n		<tr>\r\n			<td style=\"text-align: center;\"><strong>নাম</strong><strong>: </strong>দেবব্রত সরকার</td>\r\n			<td style=\"text-align: center;\"><strong>পদবী</strong><strong>:</strong><span style=\"color:rgb(68, 68, 68); font-family:adorsholipi,arial,sans-serif; font-size:14px\">&nbsp;সম্পাদক</span></td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"text-align: center;\"><strong>জন্ম</strong><span style=\"color:rgb(68, 68, 68); font-family:adorsholipi,arial,sans-serif; font-size:14px\">&nbsp;</span><strong>তারিখ</strong><strong>:</strong><span style=\"color:rgb(68, 68, 68); font-family:adorsholipi,arial,sans-serif; font-size:14px\">&nbsp;০১ জানুয়ারী</span></td>\r\n			<td style=\"text-align: center;\"><strong>ন্যাশনাল</strong><span style=\"color:rgb(68, 68, 68); font-family:adorsholipi,arial,sans-serif; font-size:14px\">&nbsp;</span><strong>আইডি</strong><span style=\"color:rgb(68, 68, 68); font-family:adorsholipi,arial,sans-serif; font-size:14px\">&nbsp;</span><strong>কার্ড</strong><strong>:</strong><span style=\"color:rgb(68, 68, 68); font-family:adorsholipi,arial,sans-serif; font-size:14px\">&nbsp;</span></td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"text-align: center;\"><strong>ধর্ম</strong><strong>&nbsp;:</strong><span style=\"color:rgb(68, 68, 68); font-family:adorsholipi,arial,sans-serif; font-size:14px\">&nbsp;সনাতন ধর্ম</span></td>\r\n			<td style=\"text-align: center;\"><strong>পিতার</strong><span style=\"color:rgb(68, 68, 68); font-family:adorsholipi,arial,sans-serif; font-size:14px\">&nbsp;</span><strong>নাম:&nbsp;</strong><span style=\"color:rgb(68, 68, 68); font-family:adorsholipi,arial,sans-serif; font-size:14px\">নিখিল নারায়ন সরকার</span></td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"text-align: center;\"><strong>মাতার</strong><span style=\"color:rgb(68, 68, 68); font-family:adorsholipi,arial,sans-serif; font-size:14px\">&nbsp;</span><strong>নাম:&nbsp;</strong><span style=\"color:rgb(68, 68, 68); font-family:adorsholipi,arial,sans-serif; font-size:14px\">নির্মলা রানী সরকার</span></td>\r\n			<td style=\"text-align: center;\"><strong>বৈবাহিক</strong><span style=\"color:rgb(68, 68, 68); font-family:adorsholipi,arial,sans-serif; font-size:14px\">&nbsp;</span><strong>অবস্থা</strong><strong>:&nbsp;</strong><span style=\"color:rgb(68, 68, 68); font-family:adorsholipi,arial,sans-serif; font-size:14px\">বিবাহিত</span></td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"text-align: center;\"><strong>স্থায়ী</strong><span style=\"color:rgb(68, 68, 68); font-family:adorsholipi,arial,sans-serif; font-size:14px\">&nbsp;</span><strong>ঠিকানা</strong><span style=\"color:rgb(68, 68, 68); font-family:adorsholipi,arial,sans-serif; font-size:14px\">: শীল বাড়ী, গ্রাম-খাড়খাদিয়া, ডাকঘর-চান্দ্রা-৩৬৫১, উপজেলা-ফরিদগন্জ&nbsp;, জেলা: চাঁদপুর।</span></td>\r\n			<td style=\"text-align: center;\"><strong>বর্তমান</strong><span style=\"color:rgb(68, 68, 68); font-family:adorsholipi,arial,sans-serif; font-size:14px\">&nbsp;</span><strong>ঠিকানা:</strong><span style=\"color:rgb(68, 68, 68); font-family:adorsholipi,arial,sans-serif; font-size:14px\">&nbsp;শীল বাড়ী, গ্রাম-খাড়খাদিয়া, ডাকঘর-চান্দ্রা-৩৬৫১,উপজেলা-ফরিদগন্জ&nbsp;, জেলা: চাঁদপুর ।</span></td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"text-align: center;\"><strong>মোবাইল :</strong></td>\r\n			<td style=\"text-align: center;\">-</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"text-align: center;\"><strong>ই-মেইল</strong></td>\r\n			<td style=\"text-align: center;\">sbc.cooperativesocietyltd@gmail.com</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n\r\n<p>&nbsp;</p>\r\n');
