INSERT INTO `managment_info` (`id`, `name`, `image`, `designation`, `details`, `posted_by`, `created_at`) VALUES
(1, 'বীর মুক্তিযোদ্ধা মো. আব্দুস সালাম', '1775036186_1.jpg', 'সভাপতি', 'বীর মুক্তিযোদ্ধা মো. আব্দুস সালাম, ৩১ মার্চ ১৯৫৩ সালে জন্মগ্রহণ করেন। তাহার পিতা মো. আব্দুল মজিদ, মাতা মরহুম আমেনা বেগম। তিনি ঢাকা জেলার স্থায়ী বাসিন্দা। বীর মুক্তিযোদ্ধা মো. আব্দুস সালাম একজন সফল সমবায়ী, ক্রীড়া সংগঠক ও সক্রিয় রাজনীতিবিদ। তিনি বাংলাদেশ কো-অপারেটিভ ইন্স্যুরেন্স লি: ও বাংলাদেশ কো-অপারেটিভ মার্কেটিং লি: এর সাবেক সভাপতি। এছাড়া তিনি বাংলাদেশ সমবায় ব্যাংক লি: এর সহ-সভাপতি ছিলেন। তিনি ঢাকা ওয়ান্ডার্স ক্লাব এর আহ্বায়ক, বাংলাদেশ অ্যাথলেটিক্স ফেডারেশন এর সাবেক সভাপতি ও সাউভ এশিয়ান অ্যাথলেটিক্স অ্যাসোসিয়েশন এর সাবেক সহ-সভাপতি। তিনি মোহাম্মদপুর কেন্দ্রীয় কলেজ এবং কিশলয় বালিকা বিদ্যালয় ও কলেজ, ঢাকা এর সভাপতি। এছাড়া ফকিরেরপুল সরকারী প্রাথমিক বিদ্যালয় এর প্রতিষ্ঠাতা ও সভাপতি। ফকিরেরপুল জামে মসজিদ ও হাফেজিয়া মাদ্রাসা, ঢাকা এর সম্পাদক ও মোতওয়ালী এবং বায়তুল মজিদ জামে মসজিদ, কাজীরবাগ, ঢাকা এর সভাপতি ও মোতওয়ালী। মুক্তিযোদ্ধা বহুমুখী কল্যান কেন্দ্র, ঢাকা মহানগর এর সভাপতি, পরিবেশ উন্নয়ন সংস্থা বাংলাদেশ এর সভাপতি। সাপ্তাহিক খবরা-খবর পত্রিকার সম্পাদক। তিনি অবিভক্ত ঢাকা সিটি কর্পোরেশন এর ডেপুটি মেয়র ছিলেন। বর্তমানে বাংলাদেশ জাতীয়তাবাদী দল (বিএনপি) চেয়ারপার্সনের উপদেষ্টা। এছাড়া তিনি ঢাকা মহানগর দক্ষিণ বিএনপির সাবেক আহ্বায়ক, অবিভক্ত ঢাকা মহানগর বিএনপির সাবেক সাধারণ সম্পাদক ও বাংলাদেশ জাতীয়তাবাদী দল (বিএনপি) এর সাবেক অর্থ বিষয়ক সম্পাদক। একজন সফল সংগঠক হিসেবে তিনি আমেরিকা, ইউরোেপ ও অস্ট্রেলিয়াসহ বিভিন্ন দেশ সফর করেছেন।', 'admin', '2026-03-30 09:18:06'),
(2, 'মো. জসিম উদ্দিন', '1775362675_1704520853_filename.jpg', 'সম্পাদক', 'মোঃ জসিম উদ্দিন ১৯৮০ সালের ডিসেম্বর মাসে চাঁদপুর জেলার ফরিদগঞ্জ উপজেলার সকদিরামপুর গ্রামে জন্মগ্রহণ করেন। তার পিতা মরহুম আব্দুছ ছাত্তার শেখ বাংলাদেশ পানি উন্নয়ন বোর্ডে কর্মরত ছিলেন। মাতা নূরজাহান বেগম গৃহিনী। আপন বড়ভাইসহ স্থানীয় প্রতিবেশী সিনিয়র ভাইদের বেকারত্ব দেখে নিজে চাকরির পেছনে না ঘুরে চাকরি দেওয়ার স্বপ্ন নিয়ে স্নাতক ১ম বর্ষে অধ্যয়নরত থাকা অবস্থায় তিনি এলাকার কয়েকজন শিক্ষিত বেকার যুবককে একত্রিত করে ১৯৯৮ সালে অনানুষ্ঠানিকভাবে এবং স্নাতক পাশ করার পর ২০০১ সালে আনুষ্ঠানিকভাবে গঠন করেন চান্দ্রা শিক্ষিত বেকার যুব বহুমুখী সমবায় লিঃ। তার উদ্ভাবনী ও সৃজনশীল নেতৃত্বে মাত্র ১২,৩০০ টাকা মূলধন নিয়ে চালু হওয়া প্রতিষ্ঠানের বর্তমান মূলধন ১৫০ কোটি টাকারও বেশী। তার প্রতিষ্ঠান হতে গত ২০ বছরে প্রায় ৫,০০০ জন বেকারের কর্মসংস্থানের সুযোগ সৃষ্টি করা হয় এবং বিভিন্ন প্রকল্পের বিপরীতে প্রায় ২ হাজার কোটি টাকা বিনিয়োগ প্রদান করা হয়েছে। কর্মসংস্থান সৃষ্টি ও উদ্যোক্তা তৈরি করার সাফল্যের স্বীকৃতি স্বরূপ ২০০৩ ও ২০১০ সালে তার নেতৃত্বাধীন চান্দ্রা সমিতি দেশের শ্রেষ্ঠ সমবায় প্রতিষ্ঠান হিসেবে এবং শ্রেষ্ঠ যুব সংগঠক হিসেবে তিনি নিজে ২০০৮ সালে জাতীয় সমবায় পুরস্কারে ভূষিত হয়ে মাননীয় প্রধানমন্ত্রী হতে স্বর্ণপদক গ্রহণ করেন। সফল তরুন উদ্যোক্তা হিসেবে তার সাফল্য নিয়ে বহুল প্রচারিত জাতীয় দৈনিক প্রথমআলো পত্রিকা ০৫ নভেম্বর ২০১৫ তারিখে ”তুমুল তারুন্য” নামে ফিচার প্রকাশ করে এবং মাছরাঙ্গা টেলিভিশন ০৬ নভেম্বর ২০১৫ তারিখে রাঙ্গা সকাল অনুষ্ঠানে লাইভ শো প্রচার করে। এছাড়াও বিভিন্ন টেলিভিশন চ্যানেল এবং জাতীয় ও স্থানীয় বিভিন্ন পত্র-পত্রিকায় তার সাফল্যগাঁথা প্রচার করে। তিনি জাতীয় ও জেলা পর্যায়ে অসংখ্য পুরষ্কার ও সম্মাননা পদকে ভূষিত হন। তিনি বাংলাদেশ সমবায় ব্যাংক লিঃ পদক; জাতীয় সমবায় মেলা-২০১০ পদক; রবীন্দ্র-নজরুল সম্মাননা-২০১২ পদকলাভ করেন।এছাড়া তিনি উপজেলা প্রশাসন; ফরিদগঞ্জ; চাঁদপুর প্রেসক্লাব, চাঁদপুর টেলিভিশন সাংবাদিক ফোরাম, চাঁদপুর রোটারি ক্লাব, ফরিদগঞ্জ লেখক ফোরাম; গ্রামীণ ফোন জাতীয় ইংলিশ উৎসব, চাঁদপুর কণ্ঠ, চাঁদপুর প্রবাহ, চাঁদপুর দিগন্ত, চাঁদপুর প্রতিদিন, চাঁদপুর দর্পণ, চাঁদপুর জমিন, আলোকিত চাঁদপুর, চাঁদপুর সংবাদ, সাপ্তাহিক আলোকিত ফরিদগঞ্জ এবং সাংস্কৃতিক সংগঠন অনন্যা নাট্য গোষ্ঠী, নৃত্যধারা, মেঘনা থিয়েটার, কল্পনা নাট্য একাডেমী, বর্ণচোরা নাট্য গোষ্ঠী, খেলাঘর আসর হতে সম্মাননা ক্রেস্ট লাভ করেন। মধ্যস্বত্বভোগীর দৌরাত্ব কমিয়ে উৎপাদক ও ভোক্তার স্বার্থ সংরক্ষণের লক্ষ্যে তিনি ২০০৮ সালে চাঁদপুরে এসবি সমবায় বাজার নামে ন্যায্যমূল্যের দোকান চালু করলে চাঁদপুর জেলাসহ সমগ্র বাংলাদেশে ব্যাপক সাড়া জাগায় এবং পরবর্তীতে তার মডেলটি অনুসরণ করে সমবায় বিভাগ হতে সারাদেশে সমবায় বাজার চালু করা হয়। তিনি চান্দ্রা সমিতির প্রতিষ্ঠাকালীন সভাপতি ছাড়াও ১৫ বছরের বেশী সময় ব্যবস্থাপনা পরিচালক হিসেবে দায়িত্ব পালন করেন এবং বর্তমানে পুনরায় নির্বাচিত হয়ে সভাপতি হিসেবে নিষ্ঠার সহিত দায়িত্ব পালন করেছেন। গণপ্রজাতন্ত্রী বাংলাদেশ সরকারের স্থানীয় সরকার, পল্লী উন্নয়ন ও সমবায় মন্ত্রণালয়ের প্রজ্ঞাপন নং-পউসবি/প্রঃ শাঃ-৩/স-১৪/২০০৮/৪৩০; তারিখ ২২ জুন ২০১০ খ্রীঃ মূলে “সমবায় উন্নয়ন তহবিল জাতীয় পরিচালনা কমিটির” সদস্য হিসেবে দুই (২) বছরের জন্য এবং প্রজ্ঞাপন নং- ৪৭.০৩.২.০২৩.০৬১.০০২.২০১২.৩৮৪; তারিখ ০৬ আগস্ট ২০১৪ খ্রীঃ মূলে স্থানীয় সরকার, পল্লী উন্নয়ন ও সমবায় মন্ত্রণালয়ের মাননীয় মন্ত্রীর নেতৃত্বাধীন জাতীয় সমবায় পুরস্কার “জাতীয় বাছাই কমিটির” সদস্য হিসেবে দুই (২) বছরের জন্য সুনামের সহিত দায়িত্ব পালন করেন। তিনি ০৩/০৫/২০১২ তারিখে সমবায় অধিদপ্তর কর্তৃক মনোনীত হয়ে “ বাংলাদেশ সমবায় বাজার কনসেটিয়াম” এর পরিচালনা কমিটির সদস্য হিসেবে দায়িত্ব পালন করেন। তিনি ওয়ার্ল্ড কাউন্সিল অফ ক্রেডিট ইউনিয়নের আমন্ত্রণে ২০২৩ সালে কানাডায় অনুষ্ঠিত ওয়ার্ল্ড ক্রেডিট ইউনিয়ন কনফারেন্স অংশগ্রহন করেন। এছাড়া গণপ্রজাতন্ত্রী বাংলাদেশ সরকারের মনোনয়নে থাইল্যান্ড এবং এ্যাসোসিয়েশন অব এশিয়ান কনফেডারেশন অব ক্রেডিট ইউনিয়নস এর আমন্ত্রণে ইন্দোনেশিয়া ভ্রমণ করাসহ তিনি বিভিন্ন সময়ে সিংগাপুর, মালয়েশিয়া, ভারত, সংযুক্ত আরব আমিরাত এবং সৌদি আরব সফর করেন। তিনি চাঁদপুর প্রেসক্লাব, চাঁদপুর ডায়াবেটিক হাসপাতাল, চাঁদপুর রেডক্রিসেন্ট সোসাইটি এবং রোটারী ক্লাব অব চাঁদপুরের আজীবন সদস্য। তিনি বিবাহিত ও ২ সন্তানের জনক।', 'admin', '2026-03-30 09:18:06'),
(3, 'জনাব কাজী নাজমুস সা\'দাত এডভোকেট', '1775036235_2.jpg', 'সহ-সভাপতি', 'কাজী নাজমুস সা\'দাত, এডভোকেট, কুমিল্লা জেলার বরুড়া উপজেলাধীন পয়ালগাছা ইউনিয়নের দোঘই গ্রামের এক সম্ভ্রান্ত মুসলিম পরিবারে ১৯৫৯ সালের ১১ জানুয়ারি জন্মগ্রহণ করেন। পিতা মরহুম কাজী আবু মিয়া, মাতা মরহুমা হাছিনা বেগম। ছাত্র অবস্থায় ১৯৭৪ খ্রি: পয়ালগাছা (উত্তর) ইউনিয়ন বহুমুখী সমবায় সমিতি লিঃ এর সদস্য হিসাবে সমবায় আন্দোলনের সাথে জড়িত হন। তিনি বর্তমানে কুমিল্লা কেন্দ্রীয় সমবায় ব্যাংক লিঃ এর সভাপতি। ইতোপূর্বে ২০০০ খ্রি: হতে ২০০৯ খ্রি: ও ২০২০-২০২৩ খ্রি: পর্যন্ত ৪ মেয়াদে কুমিল্লা কেন্দ্রীয় সমবায় ব্যাংক লিঃ এর সভাপতির দায়িত্ব পালন করেন। তিনি কুমিল্লা জেলা সমবায় ইউনিয়নের সভাপতি হিসাবে ০৪ মেয়াদে দায়িত্ব পালন করেন। তিনি ২০০৪ সালে শ্রেষ্ঠ সমবায়ী হিসেবে জাতীয় সমবায় পুরস্কারে ভূষিত হন। তিনি পেশায় আইনজীবী, বাংলাদেশ সুপ্রীম কোর্ট বার এসোসিয়েশন ও কুমিল্লা জেলা আইনজীবী সমিতির সদস্য। কুমিল্লা জজকোর্টের পি.পি এবং নারী ও শিশু নির্যাতন দমন ট্রাইব্যুনাল, কুমিল্লার স্পেশাল পি.পি হিসাবে দায়িত্ব পালন করেন। কুমিল্লা জেলা আইনজীবী সমিতির সভাপতি হিসাবে দুইবার এবং সাধারণ সম্পাদক হিসেবে দায়িত্ব পালন করেন। গরীব ও অসহায় বিচার প্রার্থী জনগণকে বিনা টাকায় আইনী সহায়তাকারী প্রতিষ্ঠান ব্লাস্ট কুমিল্লা ইউনিটের সভাপতি হিসেবে দায়িত্ব পালন করেন। আন্তর্জাতিক সেবা সংগঠন এপেক্স ক্লাব অব কুমিল্লার সভাপতি ও সাধারণ সম্পাদক এবং এপেক্স ক্লাব অব বাংলাদেশের জেলা গভর্ণর-৩ হিসাবে দায়িত্ব পালন করেন। তাছাড়া শিক্ষা, সংস্কৃতি, ধর্মীয় ও বিভিন্ন সামাজিক কর্মকান্ডের সাথে জড়িত আছেন। এ পর্যন্ত তিনি আমেরিকা সহ পৃথিবীর ১৩টি দেশে ভ্রমণ করেন।', 'admin', '2026-03-30 09:18:06'),
(4, 'জনাব মোঃ নজরুল ইসলাম', '1775036273_3.jpg', 'সহ-সভাপতি', 'মোঃ নজরুল ইসলাম ঢাকা সেন্ট্রাল কো-অপারেটিভ ব্যাংক লিঃ (৩নং আহসান উল্লাহ রোড, ইসলামপুর, ঢাকা-১১০০) এর ৩৩তম সভাপতি। এ প্রতিষ্ঠানে পরিচালক হিসেবে অতিবাহিত করেছেন দীর্ঘসময়। তিনি ১৯৭২ সালে ৩১শে জানুয়ারি গাজীপুর জেলার কাপাসিয়া উপজেলাধীন কুড়িয়াদী গ্রামের তালুকদার বংশের এক সম্ভ্রান্ত মুসলিম পরিবারে জন্মগ্রহন করেন। তার পিতা মৃত জনাব ওসমান তালুকদার ছিলেন সেই গ্রামের একজন সুপরিচিত ব্যক্তি ও বিশিষ্ট ব্যবসায়ী। মাতা ফজিলাতুন নেসা ছিলেন সন্তান লালন-পালনে দায়িত্বশীল গৃহিনী। জনাব মোঃ নজরুল ইসলাম তালুকদার সরকারি জগন্নাথ কলেজ হতে পদার্থবিজ্ঞান বিভাগে এম.এস.সি ডিগ্রি লাভকরেন। শিক্ষকতাকে পেশা হিসেবে বেছে নিয়ে পার করেছেন জীবনের অর্ধেকের বেশির সময়। তার সহধর্মনী রুনা লায়লা, বেসরকারি মাধ্যমিক বিদ্যালয়ের বিজ্ঞান বিষয়ের একজন সিনিয়র শিক্ষিকা। উভয়ের তত্ত্বাবধানে লালিত পালিত হয়ে আসছে ০২ কন্যা সন্তান এবং ০১টি পুত্র সন্তান।\r\n', 'admin', '2026-03-30 09:18:06'),
(6, 'জনাব মোঃ ইকবাল আজম', '1775036290_5.jpg', 'পরিচালক (অডিট)', 'মোঃ ইকবাল আজম চাঁদপুর জেলার স্থায়ী বাসিন্দা। তার পিতা মোঃ আবুল কালাম মজুমদার সোনালী ব্যাংকের অবসরপ্রাপ্ত কর্মকর্তা এবং মাতা (মৃত) মিসেস হাওয়া বেগম। মোঃ ইকবাল আজম বাংলাদেশ জাতীয় সমবায় ইউনিয়নের পরিচালক (অডিট) ছাড়াও চাঁদপুর জেলা সমবায় ইউনিয়ন এর সভাপতি, দি চাঁদপুর মাল্টিপারপাস কো-অপরেটিভ সোসাইটি লিঃ এর সভাপতি ও জুন হাউজিং কো-অপারেটিভ সোসাইটি লিঃ এর সভাপতি হিসেবে দায়িত্ব পালন করছেন। তিনি চাঁদপুর সেন্ট্রাল কো-অপারেটিভ ব্যাংক লিঃ এর সরকার মনোনীত পরিচালক। এছাড়াও তিনি সেন্ট্রাল কো-অপারেটিভ ফোরাম-চাঁদপুর এর সভাপতি হিসেবে (তিন মেয়াদ) দায়িত্ব পালন করেছেন। তার শিক্ষাগত যোগ্যতা বি.এস.এস (সম্মান), এম.এস.এস (অর্থনীতি), এলএল.বি। তিনি বিবাহিত এবং তিন সন্তানের জনক।\r\n', 'admin', '2026-03-30 09:18:06'),
(10, 'জনাব মোঃ লতিফুর রহমান মোল্লা', '1775036310_6.jpg', 'পরিচালক (হিসাব)', 'মোঃ লতিফুর রহমান মোল্লা ১৯৬৮ সালে ঢাকার মাতুয়াইল, যাত্রাবাড়ী জন্মগ্রহণ করেন। তিনি বাংলাদেশ কো-অপারেটিভ ইন্সুরেন্স লিমিটেড এর সচিব, আশা সঞ্চয় সমবায় সমিতি লিমিটেড এর সদস্য। এছাড়া বীর মুক্তিযোদ্ধা হাফিজুর রহমান অলি হাই স্কুল এর সভাপতি ও মাতুয়াইল উত্তর পাড়া আল-আকসা জামে মসজিদ কমিটির সাধারণ সম্পাদক। তিনি এয়ারওয়ে ট্রাভেলস অ্যান্ড ট্যুরস এর ব্যবস্থাপনা পরিচালক। তাহার শিক্ষাগত যোগ্যতা এম.এ।\r\n', 'Ahmed Miraz', '2026-03-31 05:12:26'),
(11, 'জনাব মোঃ আবুল হোসাইন', '1775036327_7.jpg', 'পরিচালক (ঢাকা ও ময়মনসিংহ বিভাগ)', 'মোঃ আবুল হোসাইন ১৯৬৮ সালের ২৬শে অক্টোবর ময়মনসিংহ জেলার ফুলপুর উপজেলাধীন রূপসী ইউনিয়নের নগর বেড়া গ্রামে এক সম্ভ্রান্ত মুসলিম পরিবারে জন্মগ্রহন করেন। তিনি রূপসী উচ্চ বিদ্যালয় থেকে মাধ্যমিক ও ফুলপুর ডিগ্রি কলেজ হতে উচ্চ মাধ্যমিক পাশ করে ঢাকা বিশ্ববিদ্যালয়ের অধীনে স্নাতক ডিগ্রি লাভ করেন। তিনি একজন সফল সমবায়ী ও বিশিষ্ট ব্যবসায়ী। তিনি ২০০৭ সালে রূপসী বাংলা বহুমুখী সমবায় সমিতি লিঃ গঠন করেন। বর্তমানে রূপসী বাংলা বহুমুখী সমবায় সমিতি লিঃ ও রূপসী বাংলা কেন্দ্রীয় সমবায় সমিতি লিঃ এর সভাপতি হিসাবে দায়িত্ব পালন করছেন। এছাড়া ময়মনসিংহ জেলা সমবায় ইউনিয়নের সভাপতি। তিনি বাংলাদেশ সমবায় বাজার কনসোর্টিয়াম সমিতির প্রতিষ্ঠাকালীন পরিচালক হিসাবে দায়িত্ব পালন করেছেন। একই সাথে মোঃ আবুল হোসাইন রূপসী বাংলা ইন্টারন্যাশনাল লিঃ এর ব্যবস্থাপনা পরিচালক হিসাবে দায়িত্ব পালন করছেন। তিনি বিবাহিত ও দুই কন্যা সন্তানের জনক। তাহার স্ত্রী পলি শিকদারও একজন সফল সমবায়ী।', 'Ahmed Miraz', '2026-03-31 05:13:59'),
(12, 'জনাব মোঃ মনিরুজ্জামান', '1775036340_8.jpg', 'পরিচালক (খুলনা বিভাগ)', 'মোঃ মনিরুজ্জামান ১৯৬৬ সনের ১১ই অক্টোবর কুষ্টিয়া জেলার আলামপুর ইউনিয়নে কাথুলিয়া গ্রামে সম্ভ্রান্ত মুসলিম পরিবারে জন্মগ্রহণ করেন। তাহার পিতা মৃত মুসলিমউজ্জামান, মাতা মোছাঃ আকলিমা জামান। তিনি প্রতিষ্ঠাতা ও চেয়ারম্যান, অর্ণব জনকল্যাণ বহুমুখী সমবায় সমিতি লিঃ, কুষ্টিয়া সদর, কুষ্টিয়া। এছাড়া কুষ্টিয়া জেলা সমবায় ইউনিয়নের সভাপতি। দেশের সর্বপ্রথম প্রতিষ্ঠিত বেসরকারি সেবামুলক প্রতিষ্ঠান স্বনির্ভর বাংলাদেশ এ ১৯৯০ সাল থেকে বিভিন্ন পদে বাংলাদেশের বিভিন্ন জেলায় দায়িত্বপালন করেন এবং ২০১৭ সাল থেকে প্রধান কার্যালয়ে সহকারী পরিচালক হিসাবে দায়ীত্ব পালন করে যাচ্ছেন। তার স্ত্রী সুলতানা নাজনিন নাহার। তাহার একমাত্র কন্যা সন্তান ডাঃ নৌশিন তাবাসসুম অর্ণব।\r\n', 'Ahmed Miraz', '2026-03-31 05:14:54'),
(13, 'জনাব মোঃ ইউসুফ হাওলাদার', '1775036352_9.jpg', 'পরিচালক (বরিশাল বিভাগ)', 'মোঃ ইউসুফ হাওলাদার ভোলা সদর উপজেলার কানাইনগর গ্রামে পঞ্চায়েত বাড়ীতে জন্ম গ্রহন করেন। তার পিতা মরহুম মন্তাজ উদ্দিন হাওলাদার ও মাতা বিবি হাজেরা বেগম। ১৯৮২ সালে প্রতিষ্ঠিত দড়িরাম সংকর সমবায় সঞ্চয় ও ঋনদান সমবায় সমিতি প্রতিষ্ঠাতা সম্পাদক হিসেবে সমবায়ে অঙ্গনে যাত্রা শুরু করেন। তিনি ভোলা কেন্দ্রীয় সমবায় ব্যাংক এর সহ-সভাপতি, ইতোপূর্বে উক্ত সমবায় ব্যাংকের পরিচালক ছিলেন। তিনি বাংলাদেশ সমবায় জুট সোসাইটি লিঃ এর বরিশাল বিভাগের নির্বাচিত প্রতিনিধি। ভূমি উন্নয়ন ব্যাংক ভোলার সদস্য। বাংলাদেশ সমবায় মার্কেটিং সোসাইটি লিঃ এর পরিচালক (বরিশাল বিভাগ)। তিনি বিবাহিত জীবনে ২ পুত্র ১ কন্যার জনক। তার প্রথম ছেলে প্রকৌশলী মোঃ আবদুর রহিম রাসেল বাংলাদেশ শিক্ষা অধিদপ্তরে এবং ২য় ছেলে প্রকৌশলী মোঃ নিয়াজ মোরশেদ, বাংলাদেশ পানি উন্নয়ন বোর্ড, ঢাকায় কর্মরত রয়েছে।', 'Ahmed Miraz', '2026-03-31 05:15:45');
