(1, 'Bangladeshi');
INSERT INTO `news` (`id`, `headline`, `details`, `status`, `created_at`, `posted_by`) VALUES
(1, 'Growing Demand for Planned Housing Projects', 'The demand for well-planned residential communities continues to grow as people increasingly look for secure, comfortable, and well-connected places to live. Modern housing projects with proper roads, green spaces, utility facilities, and community amenities are becoming more attractive to homebuyers.', 1, '2026-03-28 09:15:59', 'Admin'),
(2, 'Real Estate Sector Embraces Digital Transformation', 'Technology is transforming the real estate industry. Online plot booking, digital payments, virtual property tours, online applications, and automated customer services are making property transactions faster and more convenient for buyers.', 1, '2026-03-28 09:15:59', 'Editor'),
(3, 'Important Things to Consider Before Buying Land', 'Buying land is a significant investment, and proper verification is essential before making a decision. Buyers should carefully check ownership documents, land records, registration details, location, accessibility, and project approvals to ensure a secure investment.', 1, '2026-03-28 09:15:59', 'Health Dept'),
(4, 'Eco-Friendly Housing Becomes a Growing Trend', 'Environmentally friendly housing is becoming an important trend in the real estate industry. Modern developments are increasingly focusing on green spaces, natural lighting, proper ventilation, energy efficiency, water management, and sustainable construction practices.', 1, '2026-03-28 09:15:59', 'Education Dept'),
(11, 'Infrastructure Development Boosts Property Potential', 'Improved roads, transportation networks, educational institutions, healthcare facilities, and commercial centers can significantly increase the attractiveness of residential areas. As infrastructure expands, previously less-developed locations can become promising destinations for future property investment.', 1, '2026-03-29 00:49:50', 'Ahmed Miraz');
