INSERT INTO `notice_board` (`id`, `title`, `description`, `filename`, `publish_date`, `status`) VALUES
(50, 'চান্দ্রা শিক্ষিত বেকার যুব বহুমুখী সমবায় সমিতি লিঃ  এর ২২তম বার্ষিক সাধারণ সভার নোটিশ  সংযুক্ত ফাইলে দেয়া হ’ল।', '<p style=\"text-align: center;\">শিক্ষিত বেকার যুব বহুমূখী সমবায় সমিতি লিঃ এর পক্ষ থেকে আপনাকে জানাই শুভেচ্ছা |</p>', '62f88b0a1f7c9-61f244d3e38c1-22th.jpg', '2022-08-14', 2),
(58, 'মতলব শিক্ষিত বেকার সঞ্চয় ও ঋণদান সমবায় সমিতি লি. এর বার্ষিক সাধারণ সভা ০৮ ফেব্রুয়ারী ২০২২ তারিখ সকাল ১০ টায় সমিতির কার্যালয়ে অনুষ্ঠিত হয়েছে এবং কচুয়া শিক্ষিত বেকার সঞ্চয় ও ঋণদান সমবায় সমিতি লি. এর বার্ষিক সাধারণ সভা ০৯ ফেব্রুয়ারী ২০২২ তারিখ সকাল ১০ টায় সমিতির কার্যালয়ে অনুষ্ঠিত হয়েছে।', '<p style=\"text-align: center;\">শিক্ষিত বেকার যুব বহুমূখী সমবায় সমিতি লিঃ এর পক্ষ থেকে আপনাকে জানাই শুভেচ্ছা |</p>', '', '2022-02-10', 2),
(59, 'শিক্ষিত বেকার সঞ্চয় ও ঋণদান সমবায় সমিতি লি. এর ৯ম বার্ষিক সাধারণ সভা ১২.০২.২০২২ তারিখে সকাল ১০ টায় প্রেস ক্লাব ভবন মাল্টিপারপাস হল, চাঁদপুরে অনুষ্ঠিত হয়।', '<p style=\"text-align: justify;\">শিক্ষিত বেকার সঞ্চয় ও ঋণদান সমবায় সমিতি লি. এর ৯ম বার্ষিক সাধারণ সভা ১২.০২.২০২২ তারিখে সকাল ১০ টায় প্রেস ক্লাব ভবন মাল্টিপারপাস হল, চাঁদপুরে অনুষ্ঠিত হয়। সভায় সভাপতিত্ব করেন ৯ম বার্ষিক সাধারণ সভার সভাপতি জনাব মো. জসিম উদ্দিন শেখ এবং প্রধান অতিথি হিসেবে উপস্থিত ছিলেন জনাব মো. আবু তাহের চৌধুরী; ব্যবস্থাপনা কমিটিসহ সকল সমিতির সদস্যগণ এবং কর্মকর্তাবৃন্দ এসময় উপস্থিত ছিলেন।</p>', '', '2022-02-12', 2),
(60, 'শিক্ষিত বেকার কেন্দ্রীয় সঞ্চয় ও ঋণদান সমবায় সমিতি লি. এর ৭ম বার্ষিক সাধারণ সভা ১৬.০২.২০২২ তারিখ বিকাল ০৩ টায় সমিতির প্রধান কার্যালয় ওয়্যারলেছ বাজার, ফরিদগঞ্জ রোড, চাঁদপুরে অনুষ্ঠিত হয়।', '<p style=\"text-align: justify;\">শিক্ষিত বেকার কেন্দ্রীয় সঞ্চয় ও ঋণদান সমবায় সমিতি লি. এর ৭ম বার্ষিক সাধারণ সভা ১৬.০২.২০২২ তারিখ বিকাল ০৩ টায় সমিতির প্রধান কার্যালয় ওয়্যারলেছ বাজার, ফরিদগঞ্জ রোড, চাঁদপুরে অনুষ্ঠিত হয়। সভায় সভাপতিত্ব করেন কেন্দ্রীয় সমিতির সভাপতি জনাব মো. জসিম উদ্দিন শেখ এবং অতিথি হিসেবে উপস্থিত ছিলেন যথাক্রমে জনাব মো. আবু তাহের চৌধুরী ও ডাঃ মো. সাইফুল ইসলাম সোহেল। ব্যবস্থাপনা কমিটির নেতৃবৃন্দসহ প্রতিষ্ঠানের কর্মকর্তাবৃন্দ এসময় উপস্থিত ছিলেন।</p>', '', '2022-02-16', 2),
(71, 'ছুটির বিজ্ঞপ্তি', '<p>সংশ্লিষ্ট সকলের সদয় অবগতির জন্য জানানো যাচ্ছে যে, জাতীয় শোক দিবস উপলক্যে সাধারণ ছুটির পরিপ্রেক্ষিতে আগামীকাল সোমবার, ১৫ আগস্ট ২০২২ তারিখ শিক্ষিত বেকার কেন্দ্রীয় সঞ্চয় ও ঋনদান সমিতি লিঃ এবং ওয়্যারলেছ বাজার শিক্ষিত বেকার সঞ্চয় ও ঋনদান সমবায় সমিতি লিঃ এর সাধারণ বিভাগের অফিসসমূহ বন্ধ থাকবে।</p>', '62fc98cd08c7b-14_08_2022.pdf', '2022-08-17', 2),
(101, 'অফিস আদেশ নং-৭৫', '<p>শিক্ষিত বেকার কেন্দ্রীয় সঞ্চয় ও ঋণদান সমবায় সমিতি লিঃ, ওয়ারলেছ বাজার শিক্ষিত বেকার সঞ্চয় ও ঋণদান সমিতি লিঃ এর সাধারণ বিভাগ এবং সকল সদস্য সমিতির কর্মসংস্থান ও দারিদ্র্য বিমোচন প্রকল্পভূক্ত কার্যালয়সমূহের অফিস সময়সূচি আগামী ০১ সেপ্টেম্বর ২০২২ তারিখ হতে পরবর্তী নির্দেশ না দেওয়া পর্যন্ত নিন্মবর্ণিতভাবে নির্ধারণ করা হলঃ</p>\r\n\r\n<table align=\"center\" border=\"1\" cellpadding=\"1\" cellspacing=\"1\">\r\n	<tbody>\r\n		<tr>\r\n			<td style=\"text-align:center\">শনিবার হতে বৃহস্পতিবার</td>\r\n			<td style=\"text-align:center\">সকাল ০৯ঃ০০ ঘটিকা হতে বিকাল ৪ঃ৩০ ঘটিকা</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"text-align:center\">শুক্রবার</td>\r\n			<td style=\"text-align:center\">সাপ্তাহিক ছুটি</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n\r\n<p>&nbsp;</p>', '1661777559_filename.pdf', '2022-08-29', 2),
(102, 'ছুটির বিজ্ঞপ্তি', '<p style=\"text-align:justify\">সংশ্লিষ্ট সকলের সদয় অবগতির জন্য জানানো যাচ্ছে যে, দূর্গাপূজার বিজয়দশমী উপলক্ষে ০৫ অক্টোবর, ২০২২ এবং ঈদ-ই-মিলাদুন্নবি (সাঃ) উপলক্ষে ০৯ অক্টোবর, ২০২২ সরকারি ছুটি ঘোষিত হওয়ার পরিপ্রেক্ষিতে যথাক্রমে আগামী বুধবার, ০৫ অক্টোবর, ২০২২ এবং রবিবার, ০৯ অক্টোবর, ২০২২ তারিখ শিক্ষিত বেকার কেন্দ্রীয় সঞ্চয় ও ঋণদান সমবায় সমিতি লিঃ,&quot;কর্মসংস্থান ও দারিদ্র্য বিমোচন প্রকল্প&quot; এর প্রকল্প পরিচালকের কার্যালয়সহ প্রকল্পভুক্ত সকল অফিস এবং ওয়্যারলেছ বাজার শিক্ষিত বেকার সঞ্চয় ও ঋণদান সমবায় সমিতি লিঃ এর সাধারণ বিভাগের অফিসসমূহ বন্ধ থাকবে।</p>', '1665037924_filename.jpg', '2022-10-04', 2),
(103, 'নিয়োগ বিজ্ঞপ্তি', '<p style=\"text-align:center\"><img alt=\"নিয়োগ বিজ্ঞপ্তি\" src=\"https://sbcl.coop/assets/uploads/notice/1668483241_filename.jpg\" style=\"height:1454px; width:1000px\" /></p>', '1668483241_filename.jpg', '2022-11-15', 2),
(104, 'নিয়োগ-২০২২ এর ফলাফল', '<p style=\"text-align:center\"><u><strong>১৫, ১৬, ১৭ ডিসেম্বর, ২০২২ তারিখে অনুষ্ঠিত&nbsp;ইন্টারভিউর চূড়ান্ত ফলাফল</strong></u></p>', '1671360584_filename.jpg', '2022-12-18', 1),
(105, 'নিয়োগ বিজ্ঞপ্তি ২০২৩', '<p style=\"text-align: center;\">নিন্মবর্নিত পদে আগ্রহী ব্যক্তিগণের নিকট হতে দরখাস্ত আহবান করা হচ্ছে।</p>', '1695283374_filename.jpg', '2023-09-20', 1),
(106, 'নিয়োগ বিজ্ঞপ্তি ২০২৪', '<p>নিয়োগ বিজ্ঞপ্তি ২০২৪</p>', '1728374544_filename.jpg', '2024-10-06', 1);
