INSERT INTO `page7` (`id`, `title`) VALUES
(1, '<p style=\"text-align:justify\">১৯৯৮ সালের ১৫ নভেম্বর ফরিদগঞ্জ উপজেলার চান্দ্রা বাজার ও সংলগ্ন এলাকার কয়েকজন শিক্ষিত যুবক চান্দ্রা শিক্ষিত বেকার যুব বহুমূখী সমবায় সমিতি লিমিটেড গঠন করার পর ১৭.০৬.২০০১ তারিখে সমবায় বিভাগ হতে নিবন্ধন লাভ করে। পর্যায়ক্রমে চাঁদপুর জেলাব্যাপী এ সমিতির কার্যক্রমের&nbsp;বিস্তৃতি&nbsp;ঘটে এবং ১৭টি শাখা অফিসের মাধ্যমে সদস্যদের আর্থসামাজিক উন্নয়ন, কর্মসংস্থান সৃষ্টি, উদ্যোক্তা তৈরি ও স্বনির্ভরতা অর্জনসহ বিভিন্ন আয়-বর্ধক কাজে নিয়োজিত হয়। সমিতিটি কাজের স্বীকৃতিস্বরূপ ২০০৩ ও ২০১০ সালে শ্রেষ্ঠ প্রতিষ্ঠান ও ২০০৮ সালে শ্রেষ্ঠ সংগঠক ক্যাটাগরীতে জাতীয় সমবায় পুরস্কার লাভ করে। ২০১৩ সালে সমবায় সমিতি আইন সংশোধন করে অসদস্য হতে আমানত গ্রহণ ও শাখা অফিস বন্ধ করার নির্দেশ দেওয়া হলে চান্দ্রা সমিতি সকল অসদস্যদের আমানত ফেরত প্রদান করে এবং শাখা অফিসগুলো বন্ধ করা হয়। বর্তমানে&nbsp;শিক্ষিত বেকার কেন্দ্রীয় সঞ্চয় ও ঋণদান সমবায় সমিতি &nbsp;লিমিটেড গঠন করে&nbsp;কেন্দ্রীয় সমিতির তত্ত্বাবধানে সদস্য সমিতিগুলোর কার্যক্রম পরিচালনা করা হচ্ছে।&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;