p; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nb');
INSERT INTO `pages` (`id`, `title`, `content`) VALUES
(1, 'homepage', ''),
(2, 'contacts', ''),
(3, 'mission_vision', '<p dir=\"ltr\" ><strong>Our Vision</strong></p>\n\n <p dir=\"ltr\" >Developing a happy and sustainable city</p>\n\n <p dir=\"ltr\" ><strong>Our Mission</strong></p>\n\n <p dir=\"ltr\" >Plan, develop and manage an excellent city that provides the essence of success and sustainable living.</p>\n\n <p dir=\"ltr\" ><strong>Our Values</strong></p>\n\n<ul dir=\"ltr\">\n  <li><strong><span >Accountability</span></strong><span >: We are accountable towards our government, society, partners, customers, employees and suppliers; and we instill accountability principles in our staff at all levels.</span></li>\n  <li><strong><span >Competitiveness</span></strong><span >: We are committed to our government&rsquo;s directive to achieve first position globally, in all areas of our work.</span></li>\n  <li><strong><span >Collaboration</span></strong><span >:&nbsp;We spread positive energy, and encourage teamwork and effective participation with all stakeholders.</span></li>\n  <li><strong><span >Creativity</span></strong><span >: &nbsp;Sustainable innovation is our pathway to withstand uncertainty and to be at the forefront of future cities.</span></li>\n  <li><strong><span >Transparency</span></strong><span >:&nbsp; We embrace transparency and open data in dealing with stakeholders in the public and private sectors.</span></li>\n  <li><strong><span >Happiness</span></strong><span >:&nbsp;We harness our capability and energy for people happiness, which is a top priority for our wise leadership.</span></li>\n</ul>\n'),
(4, 'weblink', '<ul>\n <li><a href=\"http://adf.ly/1nzLqn\" target=\"_blank\"><strong>Bangladesh National Portal</strong></a></li>\n <li><a href=\"http://www.pmo.gov.bd/\" target=\"_blank\"><strong>Prime Minister&#39;s Office</strong></a></li>\n <li><a href=\"http://www.lgd.gov.bd/\" target=\"_blank\"><strong>Local Govt. Division</strong></a></li>\n <li><a href=\"http://www.plandiv.gov.bd/\" target=\"_blank\"><strong>Ministry of Planning</strong></a></li>\n <li><a href=\"http://mof.gov.bd/en/\" target=\"_blank\"><strong>Ministry of Finance</strong></a></li>\n <li><a href=\"http://www.barisal.gov.bd/\" target=\"_blank\"><strong>Barisal District Portal</strong></a></li>\n <li><a href=\"https://www.bb.org.bd/\" target=\"_blank\"><strong>Bangladesh Bank</strong></a></li>\n <li><a href=\"http://www.educationboard.gov.bd\" target=\"_blank\">Education Board Bangladesh</a></li>\n <li><a href=\"http://www.bmeb.gov.bd\" target=\"_blank\">Bangladesh Madrasah Education Board</a></li>\n <li><a href=\"http://www.bteb.gov.bd\" target=\"_blank\">BTEB</a></li>\n <li><strong><a href=\"http://www.dncc.gov.bd/\">Dhaka North City Corporation</a></strong></li>\n <li>\n <p><a href=\"http://www.dhakasouthcity.gov.bd/\">Dhaka South City Corporation.</a></p>\n </li>\n <li>\n <p><a href=\"http://www.ccc.org.bd/\">Chittagong City Corporation</a></p>\n </li>\n <li>\n <p><a href=\"http://www.sylhetcitycorporationbd.org/\">Sylhet City Corporation</a></p>\n </li>\n <li>\n <p><a href=\"http://www.erajshahi.gov.bd/\">Rajshahi City Corporation</a></p>\n </li>\n <li>\n <p><a href=\"http://www.khulnacity.org/\">Khulna City Corporation</a></p>\n </li>\n <li>\n <p><a href=\"http://rpcc.gov.bd/\">Rangpur City Corporation</a></p>\n </li>\n <li>\n <p><a href=\"http://www.ncc.org.bd/\">Narayanganj City Corporation</a></p>\n </li>\n <li>\n <p><a href=\"http://cocc.gov.bd/\">Comilla City Corporation</a></p>\n </li>\n</ul>\n'),
