INSERT INTO `recruitment` (`rec_id`, `rec_job_title`, `rec_job_location`, `rec_publish_date`, `rec_last_date`, `rec_designation`, `rec_rc_id`, `rec_job_description`, `rec_status`, `rec_created_at`, `rec_created_by`, `rec_updated_at`, `rec_updated_by`) VALUES
(11, 'আইটি অফিসার নিয়োগ ২০২৩', 'চাঁদপুর', '2022-11-15', '2022-11-30', 8, 12, '<p><strong>বিভাগঃ </strong>আইটি</p>\r\n\r\n<p><strong>পদের সংখ্যাঃ </strong>১০</p>\r\n\r\n<p><strong>বয়সসীমাঃ </strong>২৫-৩৫ বছর</p>\r\n\r\n<p><strong>শিক্ষাগত যোগ্যতাঃ</strong> কম্পিউটার সাইন্স এ স্নাতক/ডিপ্লোমা।</p>\r\n\r\n<p><strong>সাকুল্য মাসিক বেতনঃ</strong>&nbsp;১৯,০০০ টাকা</p>\r\n\r\n<p><strong>অভিজ্ঞতাঃ</strong></p>\r\n\r\n<ul>\r\n	<li>কম্পিউটার হার্ডওয়্যার।</li>\r\n	<li>ল্যান ও ওয়্যারলেস নেটওয়ার্ক।</li>\r\n	<li>অটোমেশন সফটওয়্যার।</li>\r\n	<li>অন্যান্য সকল আইটি&nbsp;</li>\r\n</ul>\r\n\r\n<p style=\"text-align:justify\"><u><strong>চাকুরিকালীন সুবিধাঃ-</strong></u><br />\r\nনির্ধারিত মাসিক বেতন ছাড়াও নিয়োগকৃত ব্যক্তি বছরে দুটি উৎসব ভাতা ও একটি বিনোদন ভাতা, দ্বি-বার্ষিক ১০% হারে বেতন বৃদ্ধি, নির্ধারিত সময়ান্তে টাইমস্কেল, কন্ট্রিবিউটরি প্রভিডেন্ড ফান্ড এবং অবসরকালে এককালীন আনুতোষিকসহ প্রতিষ্ঠানের চাকুরি বিধি অনুযায়ী প্রদেয় অন্যান্য সুবিধাদি প্রাপ্য হবেন।</p>\r\n\r\n<p><u><strong>আবেদন ও নিয়োগের শর্তাবলীঃ-</strong></u></p>\r\n\r\n<ul>\r\n	<li style=\"text-align:justify\">কর্মস্থল শুধুমাত্র চাঁদপুর জেলায় সীমাবদ্ধ হলেও উপযুক্ত যোগ্যতাসম্পন্ন বাংলাদেশের যেকোনো নাগরিক আবেদন করার ও নিয়োগ পাওয়ার যোগ্য।</li>\r\n	<li style=\"text-align:justify\">মৌখিক স্বাক্ষাৎকারের মাধ্যমে প্রার্থী চূড়ান্ত করা হবে। অধিকতর অভিজ্ঞতাসম্পন্ন ব্যক্তিগণ নিয়োগের ক্ষেত্রে অগ্রাধিকার প্রাপ্য হবেন।</li>\r\n	<li style=\"text-align:justify\">নবনিয়োগকৃত ব্যক্তিকে চাকুরিতে যোগদানকালে ৩০০ (তিনশত) টাকার নন-জুডিশিয়াল স্ট্যাম্পে নির্ধারিত অঙ্গীকার প্রদান এবং ন্যূনতম একবছর শিক্ষানবিশ হিসেবে কাজ করতে হবে।</li>\r\n	<li style=\"text-align:justify\">প্রার্থীর নাম, পিতা-মাতার নাম, জাতীয় পরিচয়পত্র নম্বর, স্থায়ী ঠিকানা, বর্তমান বা যোগাযোগের ঠিকানা, মোবাইল নম্বর, ই-মেইল আইডি, জন্ম তারিখ ও বয়স, জাতীয়তা, বৈবাহিক অবস্থা, উচ্চতা, শিক্ষাগত যোগ্যতা, অভিজ্ঞতার তথ্যাবলী সম্বলিত জীবনবৃত্তান্ত এবং সদ্যতোলা রঙ্গিন ৩ (তিন) কপি পাসপোর্ট সাইজের ছবিসহ আবেদনপত্র সভাপতি, ব্যবস্থাপনা কমিটি, শিক্ষিত বেকার কেন্দ্রীয় সঞ্চয় ও ঋণদান সমবায় সমিতি লিমিটেড, ওয়্যারলেছ বাজার, ফরিদগঞ্জ রোড, চাঁদপুর সদর, চাঁদপুর-৩৬০০ এর বরাবর আগামী ৩০.১১.২০২২ তারিখ, বিকাল ৫:০০ টার মধ্যে সরাসরি বা ডাকযোগে পৌঁছানো নিশ্চিত করতে হবে।</li>\r\n	<li style=\"text-align:justify\">প্রাপ্ত আবেদন যাচাই-বাছাই করে যোগ্যতার আলোকে সংক্ষিপ্ত তালিকা প্রণয়ন করার পর মৌখিক পরীক্ষার ইন্টারভিউ কার্ড ইস্যু করা হবে। মৌখিক পরীক্ষায় অংশগ্রহণকালে প্রার্থীর জীবন বৃত্তান্তে উল্লেখ করা তথ্যের প্রমাণক হিসেবে সকল মূল সনদপত্র ও দলিলাদি, জাতীয় পরিচয়পত্র এবং ওয়ার্ড কাউন্সিলর/চেয়ারম্যান/মেয়র কর্তৃক ইস্যুকৃত নাগরিকত্বের প্রত্যয়নপত্র সঙ্গে আনতে হবে। মৌখিক পরীক্ষায় অংশগ্রহণের জন্য প্রার্থীগণকে কোনো প্রকার আর্থিক সুবিধা প্রদান করা হবেনা।</li>\r\n</ul>\r\n\r\n<p style=\"text-align:justify\"><strong>চাঁদপুর জেলাধীন সমবায় প্রতিষ্ঠান শিক্ষিত বেকার কেন্দ্রীয় সঞ্চয় ও ঋণদান সমবায় সমিতি লিমিটেড এবং সদস্য প্রাথমিক সমবায় সমিতিগুলোর জন্য আইটি অফিসার পদে নিয়োগের নিমিত্তে প্রয়োজনীয় যোগ্যতাসম্পন্ন আগ্রহী ব্যক্তিগণের নিকট হতে দরখাস্ত আহবান করা যাচ্ছে।</strong></p>\r\n', 1, '0000-00-00 00:00:00', 1, '0000-00-00 00:00:00', 1),
(12, 'ক্যাশিয়ার নিয়োগ ২০২৩', 'চাঁদপুর', '2022-11-15', '2022-11-30', 2, 12, '<p><strong>পদের সংখ্যাঃ</strong>&nbsp;৫</p>\r\n\r\n<p><strong>বয়সসীমাঃ&nbsp;</strong>২০-৩৫ বছর</p>\r\n\r\n<p><strong>শিক্ষাগত যোগ্যতাঃ</strong>&nbsp;স্নাতক</p>\r\n\r\n<p><strong>অভিজ্ঞতাঃ</strong>&nbsp;প্রযোজ্য&nbsp;নহে।</p>\r\n\r\n<p><strong>সাকুল্য মাসিক বেতনঃ</strong>&nbsp;১৫,০০০ টাকা</p>\r\n\r\n<p style=\"text-align:justify\"><u><strong>চাকুরিকালীন সুবিধাঃ-</strong></u><br />\r\nনির্ধারিত মাসিক বেতন ছাড়াও নিয়োগকৃত ব্যক্তি বছরে দুটি উৎসব ভাতা ও একটি বিনোদন ভাতা, দ্বি-বার্ষিক ১০% হারে বেতন বৃদ্ধি, নির্ধারিত সময়ান্তে টাইমস্কেল, কন্ট্রিবিউটরি প্রভিডেন্ড ফান্ড এবং অবসরকালে এককালীন আনুতোষিকসহ প্রতিষ্ঠানের চাকুরি বিধি অনুযায়ী প্রদেয় অন্যান্য সুবিধাদি প্রাপ্য হবেন।</p>\r\n\r\n<p><u><strong>আবেদন ও নিয়োগের শর্তাবলীঃ-</strong></u></p>\r\n\r\n<ul>\r\n	<li style=\"text-align:justify\">কর্মস্থল শুধুমাত্র চাঁদপুর জেলায় সীমাবদ্ধ হলেও উপযুক্ত যোগ্যতাসম্পন্ন বাংলাদেশের যেকোনো নাগরিক আবেদন করার ও নিয়োগ পাওয়ার যোগ্য।</li>\r\n	<li style=\"text-align:justify\">মৌখিক স্বাক্ষাৎকারের মাধ্যমে প্রার্থী চূড়ান্ত করা হবে। অধিকতর অভিজ্ঞতাসম্পন্ন ব্যক্তিগণ নিয়োগের ক্ষেত্রে অগ্রাধিকার প্রাপ্য হবেন।</li>\r\n	<li style=\"text-align:justify\">নবনিয়োগকৃত ব্যক্তিকে চাকুরিতে যোগদানকালে ৩০০ (তিনশত) টাকার নন-জুডিশিয়াল স্ট্যাম্পে নির্ধারিত অঙ্গীকার প্রদান এবং ন্যূনতম একবছর শিক্ষানবিশ হিসেবে কাজ করতে হবে।</li>\r\n	<li style=\"text-align:justify\">প্রার্থীর নাম, পিতা-মাতার নাম, জাতীয় পরিচয়পত্র নম্বর, স্থায়ী ঠিকানা, বর্তমান বা যোগাযোগের ঠিকানা, মোবাইল নম্বর, ই-মেইল আইডি, জন্ম তারিখ ও বয়স, জাতীয়তা, বৈবাহিক অবস্থা, উচ্চতা, শিক্ষাগত যোগ্যতা, অভিজ্ঞতার তথ্যাবলী সম্বলিত জীবনবৃত্তান্ত এবং সদ্যতোলা রঙ্গিন ৩ (তিন) কপি পাসপোর্ট সাইজের ছবিসহ আবেদনপত্র সভাপতি, ব্যবস্থাপনা কমিটি, শিক্ষিত বেকার কেন্দ্রীয় সঞ্চয় ও ঋণদান সমবায় সমিতি লিমিটেড, ওয়্যারলেছ বাজার, ফরিদগঞ্জ রোড, চাঁদপুর সদর, চাঁদপুর-৩৬০০ এর বরাবর আগামী ৩০.১১.২০২২ তারিখ, বিকাল ৫:০০ টার মধ্যে সরাসরি বা ডাকযোগে পৌঁছানো নিশ্চিত করতে হবে।</li>\r\n	<li style=\"text-align:justify\">প্রাপ্ত আবেদন যাচাই-বাছাই করে যোগ্যতার আলোকে সংক্ষিপ্ত তালিকা প্রণয়ন করার পর মৌখিক পরীক্ষার ইন্টারভিউ কার্ড ইস্যু করা হবে। মৌখিক পরীক্ষায় অংশগ্রহণকালে প্রার্থীর জীবন বৃত্তান্তে উল্লেখ করা তথ্যের প্রমাণক হিসেবে সকল মূল সনদপত্র ও দলিলাদি, জাতীয় পরিচয়পত্র এবং ওয়ার্ড কাউন্সিলর/চেয়ারম্যান/মেয়র কর্তৃক ইস্যুকৃত নাগরিকত্বের প্রত্যয়নপত্র সঙ্গে আনতে হবে। মৌখিক পরীক্ষায় অংশগ্রহণের জন্য প্রার্থীগণকে কোনো প্রকার আর্থিক সুবিধা প্রদান করা হবেনা।</li>\r\n</ul>\r\n\r\n<p style=\"text-align:justify\"><strong>চাঁদপুর জেলাধীন সমবায় প্রতিষ্ঠান শিক্ষিত বেকার কেন্দ্রীয় সঞ্চয় ও ঋণদান সমবায় সমিতি লিমিটেড এবং সদস্য প্রাথমিক সমবায় সমিতিগুলোর জন্য আইটি অফিসার পদে নিয়োগের নিমিত্তে প্রয়োজনীয় যোগ্যতাসম্পন্ন আগ্রহী ব্যক্তিগণের নিকট হতে দরখাস্ত আহবান করা যাচ্ছে।</strong></p>\r\n', 1, '0000-00-00 00:00:00', 1, '0000-00-00 00:00:00', 1),
(13, 'অভ্যর্থনা', 'চাঁদপুর', '2022-11-15', '2022-11-30', 9, 12, '<p><strong>বিভাগঃ </strong>অ্যাডমিন</p>\r\n\r\n<p><strong>পদের সংখ্যাঃ </strong>১</p>\r\n\r\n<p><strong>বয়সসীমাঃ&nbsp;</strong>২০-৩৫ বছর</p>\r\n\r\n<p><strong>শিক্ষাগত যোগ্যতাঃ</strong>&nbsp;স্নাতক</p>\r\n\r\n<p><strong>সাকুল্য মাসিক বেতনঃ</strong>&nbsp;১৩,০০০ টাকা</p>\r\n\r\n<p><strong>অভিজ্ঞতাঃ&nbsp;</strong>প্রযোজ্য&nbsp;নহে</p>\r\n\r\n<p style=\"text-align:justify\"><u><strong>চাকুরিকালীন সুবিধাঃ-</strong></u><br />\r\nনির্ধারিত মাসিক বেতন ছাড়াও নিয়োগকৃত ব্যক্তি বছরে দুটি উৎসব ভাতা ও একটি বিনোদন ভাতা, দ্বি-বার্ষিক ১০% হারে বেতন বৃদ্ধি, নির্ধারিত সময়ান্তে টাইমস্কেল, কন্ট্রিবিউটরি প্রভিডেন্ড ফান্ড এবং অবসরকালে এককালীন আনুতোষিকসহ প্রতিষ্ঠানের চাকুরি বিধি অনুযায়ী প্রদেয় অন্যান্য সুবিধাদি প্রাপ্য হবেন।</p>\r\n\r\n<p><u><strong>আবেদন ও নিয়োগের শর্তাবলীঃ-</strong></u></p>\r\n\r\n<ul>\r\n	<li style=\"text-align:justify\">কর্মস্থল শুধুমাত্র চাঁদপুর জেলায় সীমাবদ্ধ হলেও উপযুক্ত যোগ্যতাসম্পন্ন বাংলাদেশের যেকোনো নাগরিক আবেদন করার ও নিয়োগ পাওয়ার যোগ্য।</li>\r\n	<li style=\"text-align:justify\">মৌখিক স্বাক্ষাৎকারের মাধ্যমে প্রার্থী চূড়ান্ত করা হবে। অধিকতর অভিজ্ঞতাসম্পন্ন ব্যক্তিগণ নিয়োগের ক্ষেত্রে অগ্রাধিকার প্রাপ্য হবেন।</li>\r\n	<li style=\"text-align:justify\">নবনিয়োগকৃত ব্যক্তিকে চাকুরিতে যোগদানকালে ৩০০ (তিনশত) টাকার নন-জুডিশিয়াল স্ট্যাম্পে নির্ধারিত অঙ্গীকার প্রদান এবং ন্যূনতম একবছর শিক্ষানবিশ হিসেবে কাজ করতে হবে।</li>\r\n	<li style=\"text-align:justify\">প্রার্থীর নাম, পিতা-মাতার নাম, জাতীয় পরিচয়পত্র নম্বর, স্থায়ী ঠিকানা, বর্তমান বা যোগাযোগের ঠিকানা, মোবাইল নম্বর, ই-মেইল আইডি, জন্ম তারিখ ও বয়স, জাতীয়তা, বৈবাহিক অবস্থা, উচ্চতা, শিক্ষাগত যোগ্যতা, অভিজ্ঞতার তথ্যাবলী সম্বলিত জীবনবৃত্তান্ত এবং সদ্যতোলা রঙ্গিন ৩ (তিন) কপি পাসপোর্ট সাইজের ছবিসহ আবেদনপত্র সভাপতি, ব্যবস্থাপনা কমিটি, শিক্ষিত বেকার কেন্দ্রীয় সঞ্চয় ও ঋণদান সমবায় সমিতি লিমিটেড, ওয়্যারলেছ বাজার, ফরিদগঞ্জ রোড, চাঁদপুর সদর, চাঁদপুর-৩৬০০ এর বরাবর আগামী ৩০.১১.২০২২ তারিখ, বিকাল ৫:০০ টার মধ্যে সরাসরি বা ডাকযোগে পৌঁছানো নিশ্চিত করতে হবে।</li>\r\n	<li style=\"text-align:justify\">প্রাপ্ত আবেদন যাচাই-বাছাই করে যোগ্যতার আলোকে সংক্ষিপ্ত তালিকা প্রণয়ন করার পর মৌখিক পরীক্ষার ইন্টারভিউ কার্ড ইস্যু করা হবে। মৌখিক পরীক্ষায় অংশগ্রহণকালে প্রার্থীর জীবন বৃত্তান্তে উল্লেখ করা তথ্যের প্রমাণক হিসেবে সকল মূল সনদপত্র ও দলিলাদি, জাতীয় পরিচয়পত্র এবং ওয়ার্ড কাউন্সিলর/চেয়ারম্যান/মেয়র কর্তৃক ইস্যুকৃত নাগরিকত্বের প্রত্যয়নপত্র সঙ্গে আনতে হবে। মৌখিক পরীক্ষায় অংশগ্রহণের জন্য প্রার্থীগণকে কোনো প্রকার আর্থিক সুবিধা প্রদান করা হবেনা।</li>\r\n</ul>\r\n\r\n<p style=\"text-align:justify\"><strong>চাঁদপুর জেলাধীন সমবায় প্রতিষ্ঠান শিক্ষিত বেকার কেন্দ্রীয় সঞ্চয় ও ঋণদান সমবায় সমিতি লিমিটেড এবং সদস্য প্রাথমিক সমবায় সমিতিগুলোর জন্য আইটি অফিসার পদে নিয়োগের নিমিত্তে প্রয়োজনীয় যোগ্যতাসম্পন্ন আগ্রহী ব্যক্তিগণের নিকট হতে দরখাস্ত আহবান করা যাচ্ছে।</strong></p>\r\n', 1, '0000-00-00 00:00:00', 1, '0000-00-00 00:00:00', 1),
(14, 'নিয়োগ বিজ্ঞপ্তি/২০২৩ ', 'ওয়্যারলেছ বাজার, ফরিদগঞ্জ রোড, চাঁদপুর সদর, চাঁদপুর। ', '2022-11-14', '2022-11-30', 8, 13, '<p style=\"text-align:justify\">&nbsp;</p>\r\n\r\n<p style=\"text-align:justify\">অভিজ্ঞতাঃ</p>\r\n\r\n<ul>\r\n	<li>কম্পিউটার হার্ডওয়্যার।</li>\r\n	<li>ল্যান ও ওয়্যারলেস নেটওয়ার্ক।</li>\r\n	<li>অটোমেশন সফটওয়্যার।</li>\r\n	<li>অন্যান্য সকল আইটি&nbsp;</li>\r\n</ul>\r\n\r\n<p style=\"text-align:justify\"><u>চাকুরিকালীন সুবিধাঃ-</u><br />\r\nনির্ধারিত মাসিক বেতন ছাড়াও নিয়োগকৃত ব্যক্তি বছরে দুটি উৎসব ভাতা ও একটি বিনোদন ভাতা, দ্বি-বার্ষিক ১০% হারে বেতন বৃদ্ধি, নির্ধারিত সময়ান্তে টাইমস্কেল, কন্ট্রিবিউটরি প্রভিডেন্ড ফান্ড এবং অবসরকালে এককালীন আনুতোষিকসহ প্রতিষ্ঠানের চাকুরি বিধি অনুযায়ী প্রদেয় অন্যান্য সুবিধাদি প্রাপ্য হবেন।</p>\r\n\r\n<p style=\"text-align:justify\"><u>আবেদন ও নিয়োগের শর্তাবলীঃ-</u></p>\r\n\r\n<ul>\r\n	<li style=\"text-align:justify\">কর্মস্থল শুধুমাত্র চাঁদপুর জেলায় সীমাবদ্ধ হলেও উপযুক্ত যোগ্যতাসম্পন্ন বাংলাদেশের যেকোনো নাগরিক আবেদন করার ও নিয়োগ পাওয়ার যোগ্য।</li>\r\n	<li style=\"text-align:justify\">মৌখিক স্বাক্ষাৎকারের মাধ্যমে প্রার্থী চূড়ান্ত করা হবে। অধিকতর অভিজ্ঞতাসম্পন্ন ব্যক্তিগণ নিয়োগের ক্ষেত্রে অগ্রাধিকার প্রাপ্য হবেন।</li>\r\n	<li style=\"text-align:justify\">নবনিয়োগকৃত ব্যক্তিকে চাকুরিতে যোগদানকালে ৩০০ (তিনশত) টাকার নন-জুডিশিয়াল স্ট্যাম্পে নির্ধারিত অঙ্গীকার প্রদান এবং ন্যূনতম একবছর শিক্ষানবিশ হিসেবে কাজ করতে হবে।</li>\r\n	<li style=\"text-align:justify\">প্রার্থীর নাম, পিতা-মাতার নাম, জাতীয় পরিচয়পত্র নম্বর, স্থায়ী ঠিকানা, বর্তমান বা যোগাযোগের ঠিকানা, মোবাইল নম্বর, ই-মেইল আইডি, জন্ম তারিখ ও বয়স, জাতীয়তা, বৈবাহিক অবস্থা, উচ্চতা, শিক্ষাগত যোগ্যতা, অভিজ্ঞতার তথ্যাবলী সম্বলিত জীবনবৃত্তান্ত এবং সদ্যতোলা রঙ্গিন ৩ (তিন) কপি পাসপোর্ট সাইজের ছবিসহ আবেদনপত্র সভাপতি, ব্যবস্থাপনা কমিটি, শিক্ষিত বেকার কেন্দ্রীয় সঞ্চয় ও ঋণদান সমবায় সমিতি লিমিটেড, ওয়্যারলেছ বাজার, ফরিদগঞ্জ রোড, চাঁদপুর সদর, চাঁদপুর-৩৬০০ এর বরাবর আগামী ৩০.১১.২০২২ তারিখ, বিকাল ৫:০০ টার মধ্যে সরাসরি বা ডাকযোগে পৌঁছানো নিশ্চিত করতে হবে।</li>\r\n	<li style=\"text-align:justify\">প্রাপ্ত আবেদন যাচাই-বাছাই করে যোগ্যতার আলোকে সংক্ষিপ্ত তালিকা প্রণয়ন করার পর মৌখিক পরীক্ষার ইন্টারভিউ কার্ড ইস্যু করা হবে। মৌখিক পরীক্ষায় অংশগ্রহণকালে প্রার্থীর জীবন বৃত্তান্তে উল্লেখ করা তথ্যের প্রমাণক হিসেবে সকল মূল সনদপত্র ও দলিলাদি, জাতীয় পরিচয়পত্র এবং ওয়ার্ড কাউন্সিলর/চেয়ারম্যান/মেয়র কর্তৃক ইস্যুকৃত নাগরিকত্বের প্রত্যয়নপত্র সঙ্গে আনতে হবে। মৌখিক পরীক্ষায় অংশগ্রহণের জন্য প্রার্থীগণকে কোনো প্রকার আর্থিক সুবিধা প্রদান করা হবেনা।</li>\r\n</ul>\r\n\r\n<p style=\"text-align:justify\">চাঁদপুর জেলাধীন সমবায় প্রতিষ্ঠান শিক্ষিত বেকার কেন্দ্রীয় সঞ্চয় ও ঋণদান সমবায় সমিতি লিমিটেড এবং সদস্য প্রাথমিক সমবায় সমিতিগুলোর জন্য আইটি অফিসার পদে নিয়োগের নিমিত্তে প্রয়োজনীয় যোগ্যতাসম্পন্ন আগ্রহী ব্যক্তিগণের নিকট হতে দরখাস্ত আহবান করা যাচ্ছে।</p>\r\n', 1, '0000-00-00 00:00:00', 1, '0000-00-00 00:00:00', 1),
(16, 'Dummy', 'Dummy', '2023-02-24', '2023-02-20', 1, 13, '', 1, '2023-02-20 13:31:00', 1, '2023-02-22 14:38:00', 1),
(17, 'সহকারী পরিচালক নিয়োগ ২০২৩', 'চাঁদপুর', '2023-09-20', '2023-10-12', 1, 17, '<p><span style=\"color:rgb(33, 37, 41); font-family:kalpurush,sans-serif; font-size:16px\"><strong>পদের সংখ্যাঃ</strong> ০৩</span></p>\r\n\r\n<p><span style=\"color:rgb(33, 37, 41); font-family:kalpurush,sans-serif; font-size:16px\"><strong>বয়সসীমাঃ</strong> ৪</span><span style=\"color:rgb(33, 37, 41); font-family:kalpurush,sans-serif; font-size:16px\">৫ বছর</span></p>\r\n\r\n<p><strong><span style=\"color:rgb(33, 37, 41); font-family:kalpurush,sans-serif; font-size:16px\">শিক্ষাগত যোগ্যতাঃ</span></strong><span style=\"color:rgb(33, 37, 41); font-family:kalpurush,sans-serif; font-size:16px\">&nbsp;স্নাতকোত্তর।</span></p>\r\n\r\n<p><strong><span style=\"color:rgb(33, 37, 41); font-family:kalpurush,sans-serif; font-size:16px\">সাকুল্য মাসিক বেতনঃ</span></strong><span style=\"color:rgb(33, 37, 41); font-family:kalpurush,sans-serif; font-size:16px\">&nbsp;৩৬,০০০ টাকা।</span></p>\r\n\r\n<p><span style=\"color:rgb(33, 37, 41); font-family:kalpurush,sans-serif; font-size:16px\"><strong>অভিজ্ঞতাঃ</strong> ১০ বছরের বাস্তব কাজের অভিজ্ঞতা এবং কম্পিউটার পরিচালনায় দক্ষ হতে হবে।</span></p>\r\n\r\n<p><strong><span style=\"color:rgb(33, 37, 41); font-family:kalpurush,sans-serif; font-size:16px\">চাকুরিকালীন সুবিধাঃ</span></strong></p>\r\n\r\n<p><span style=\"color:rgb(33, 37, 41); font-family:kalpurush,sans-serif; font-size:16px\">নির্ধারিত মাসিক বেতন ছাড়াও নিয়োগকৃত ব্যক্তি বছরে দুটি উৎসব ভাতা ও একটি বিনোদন ভাতা, দ্বি-বার্ষিক ১০% হারে বেতন বৃদ্ধি, নির্ধারিত সময়ান্তে টাইমস্কেল, কন্ট্রিবিউটরি প্রভিডেন্ট&nbsp;ফান্ড এবং অবসরকালে এককালীন আনুতোষিকসহ প্রতিষ্ঠানের চাকুরি বিধি অনুযায়ী প্রদেয় অন্যান্য সুবিধাদি প্রাপ্য হবেন।</span></p>\r\n\r\n<p><strong><span style=\"color:rgb(33, 37, 41); font-family:kalpurush,sans-serif; font-size:16px\">আবেদন ও নিয়োগের শর্তাবলীঃ</span></strong></p>\r\n\r\n<ul>\r\n	<li>কর্মস্থল শুধুমাত্র চাঁদপুর জেলায় সীমাবদ্ধ হলেও উপযুক্ত যোগ্যতাসম্পন্ন বাংলাদেশের যেকোনো নাগরিক আবেদন করার ও নিয়োগ পাওয়ার যোগ্য।</li>\r\n	<li style=\"text-align:justify\">মৌখিক সাক্ষাৎকারের মাধ্যমে প্রার্থী চূড়ান্ত করা হবে। অধিকতর অভিজ্ঞতাসম্পন্ন ব্যক্তিগণ নিয়োগের ক্ষেত্রে অগ্রাধিকার প্রাপ্য হবেন।</li>\r\n	<li style=\"text-align:justify\">নবনিয়োগকৃত ব্যক্তিকে চাকুরিতে যোগদানকালে ৩০০ (তিনশত) টাকার নন-জুডিশিয়াল স্ট্যাম্পে নির্ধারিত অঙ্গীকার প্রদান এবং ন্যূনতম একবছর শিক্ষানবিশ হিসেবে কাজ করতে হবে।</li>\r\n	<li style=\"text-align:justify\">প্রার্থীর নাম, পিতা-মাতার নাম, জাতীয় পরিচয়পত্র নম্বর, স্থায়ী ঠিকানা, বর্তমান বা যোগাযোগের ঠিকানা, মোবাইল নম্বর, ই-মেইল আইডি, জন্ম তারিখ ও বয়স, জাতীয়তা, বৈবাহিক অবস্থা, উচ্চতা, শিক্ষাগত যোগ্যতা, অভিজ্ঞতার তথ্যাবলী সম্বলিত জীবনবৃত্তান্ত এবং সদ্যতোলা রঙ্গিন ৩ (তিন) কপি পাসপোর্ট সাইজের ছবিসহ আবেদনপত্র সভাপতি, ব্যবস্থাপনা কমিটি, শিক্ষিত বেকার কেন্দ্রীয় সঞ্চয় ও ঋণদান সমবায় সমিতি লিমিটেড, ওয়ারলেছ বাজার, ফরিদগঞ্জ রোড, চাঁদপুর সদর, চাঁদপুর-৩৬০০ এর বরাবর আগামী ১২.১০.২০২৩&nbsp;তারিখ, বিকাল ৫:০০ টার মধ্যে সরাসরি বা ডাকযোগে পৌঁছানো নিশ্চিত করতে হবে।</li>\r\n	<li style=\"text-align:justify\">প্রাপ্ত আবেদন যাচাই-বাছাই করে যোগ্যতার আলোকে সংক্ষিপ্ত তালিকা প্রণয়ন করার পর মৌখিক পরীক্ষার ইন্টারভিউ কার্ড ইস্যু করা হবে। মৌখিক পরীক্ষায় অংশগ্রহণকালে প্রার্থীর জীবন বৃত্তান্তে উল্লেখ করা তথ্যের প্রমাণক হিসেবে সকল মূল সনদপত্র, জাতীয় পরিচয়পত্র এবং ওয়ার্ড কাউন্সিলর/চেয়ারম্যান/মেয়র কর্তৃক ইস্যুকৃত নাগরিকত্বের প্রত্যয়নপত্র সঙ্গে আনতে হবে। মৌখিক পরীক্ষায় অংশগ্রহণের জন্য প্রার্থীগণকে কোনো প্রকার আর্থিক সুবিধা প্রদান করা হবেনা।</li>\r\n</ul>\r\n', 1, '2023-09-21 18:00:00', 1, '2023-09-21 18:11:00', 1),
(18, 'সহকারী ব্যবস্থাপক নিয়োগ ২০২৩', 'চাঁদপুর', '2023-09-20', '2023-10-12', 11, 17, '<p><span style=\"color:rgb(33, 37, 41); font-family:kalpurush,sans-serif; font-size:16px\"><strong>পদের সংখ্যাঃ</strong>&nbsp;১০</span></p>\r\n\r\n<p><span style=\"color:rgb(33, 37, 41); font-family:kalpurush,sans-serif; font-size:16px\"><strong>বয়সসীমাঃ</strong>&nbsp;৪০</span><span style=\"color:rgb(33, 37, 41); font-family:kalpurush,sans-serif; font-size:16px\">&nbsp;বছর</span></p>\r\n\r\n<p><strong><span style=\"color:rgb(33, 37, 41); font-family:kalpurush,sans-serif; font-size:16px\">শিক্ষাগত যোগ্যতাঃ</span></strong><span style=\"color:rgb(33, 37, 41); font-family:kalpurush,sans-serif; font-size:16px\">&nbsp;স্নাতকোত্তর।</span></p>\r\n\r\n<p><strong><span style=\"color:rgb(33, 37, 41); font-family:kalpurush,sans-serif; font-size:16px\">সাকুল্য মাসিক বেতনঃ</span></strong><span style=\"color:rgb(33, 37, 41); font-family:kalpurush,sans-serif; font-size:16px\">&nbsp;২৪,০০০ টাকা।</span></p>\r\n\r\n<p><span style=\"color:rgb(33, 37, 41); font-family:kalpurush,sans-serif; font-size:16px\"><strong>অভিজ্ঞতাঃ</strong>&nbsp;৫ বছরের বাস্তব কাজের অভিজ্ঞতা এবং কম্পিউটার পরিচালনায় দক্ষ হতে হবে</span><span style=\"color:rgb(33, 37, 41); font-family:kalpurush,sans-serif; font-size:16px\">।</span></p>\r\n\r\n<p><strong><span style=\"color:rgb(33, 37, 41); font-family:kalpurush,sans-serif; font-size:16px\">চাকুরিকালীন সুবিধাঃ</span></strong></p>\r\n\r\n<p><span style=\"color:rgb(33, 37, 41); font-family:kalpurush,sans-serif; font-size:16px\">নির্ধারিত মাসিক বেতন ছাড়াও নিয়োগকৃত ব্যক্তি বছরে দুটি উৎসব ভাতা ও একটি বিনোদন ভাতা, দ্বি-বার্ষিক ১০% হারে বেতন বৃদ্ধি, নির্ধারিত সময়ান্তে টাইমস্কেল, কন্ট্রিবিউটরি প্রভিডেন্ট&nbsp;ফান্ড এবং অবসরকালে এককালীন আনুতোষিকসহ প্রতিষ্ঠানের চাকুরি বিধি অনুযায়ী প্রদেয় অন্যান্য সুবিধাদি প্রাপ্য হবেন।</span></p>\r\n\r\n<p><strong><span style=\"color:rgb(33, 37, 41); font-family:kalpurush,sans-serif; font-size:16px\">আবেদন ও নিয়োগের শর্তাবলীঃ</span></strong></p>\r\n\r\n<ul>\r\n	<li>কর্মস্থল শুধুমাত্র চাঁদপুর জেলায় সীমাবদ্ধ হলেও উপযুক্ত যোগ্যতাসম্পন্ন বাংলাদেশের যেকোনো নাগরিক আবেদন করার ও নিয়োগ পাওয়ার যোগ্য।</li>\r\n	<li style=\"text-align:justify\">মৌখিক সাক্ষাৎকারের মাধ্যমে প্রার্থী চূড়ান্ত করা হবে। অধিকতর অভিজ্ঞতাসম্পন্ন ব্যক্তিগণ নিয়োগের ক্ষেত্রে অগ্রাধিকার প্রাপ্য হবেন।</li>\r\n	<li style=\"text-align:justify\">নবনিয়োগকৃত ব্যক্তিকে চাকুরিতে যোগদানকালে ৩০০ (তিনশত) টাকার নন-জুডিশিয়াল স্ট্যাম্পে নির্ধারিত অঙ্গীকার প্রদান এবং ন্যূনতম একবছর শিক্ষানবিশ হিসেবে কাজ করতে হবে।</li>\r\n	<li style=\"text-align:justify\">প্রার্থীর নাম, পিতা-মাতার নাম, জাতীয় পরিচয়পত্র নম্বর, স্থায়ী ঠিকানা, বর্তমান বা যোগাযোগের ঠিকানা, মোবাইল নম্বর, ই-মেইল আইডি, জন্ম তারিখ ও বয়স, জাতীয়তা, বৈবাহিক অবস্থা, উচ্চতা, শিক্ষাগত যোগ্যতা, অভিজ্ঞতার তথ্যাবলী সম্বলিত জীবনবৃত্তান্ত এবং সদ্যতোলা রঙ্গিন ৩ (তিন) কপি পাসপোর্ট সাইজের ছবিসহ আবেদনপত্র সভাপতি, ব্যবস্থাপনা কমিটি, শিক্ষিত বেকার কেন্দ্রীয় সঞ্চয় ও ঋণদান সমবায় সমিতি লিমিটেড, ওয়ারলেছ বাজার, ফরিদগঞ্জ রোড, চাঁদপুর সদর, চাঁদপুর-৩৬০০ এর বরাবর আগামী ১২.১০.২০২৩&nbsp;তারিখ, বিকাল ৫:০০ টার মধ্যে সরাসরি বা ডাকযোগে পৌঁছানো নিশ্চিত করতে হবে।</li>\r\n	<li style=\"text-align:justify\">প্রাপ্ত আবেদন যাচাই-বাছাই করে যোগ্যতার আলোকে সংক্ষিপ্ত তালিকা প্রণয়ন করার পর মৌখিক পরীক্ষার ইন্টারভিউ কার্ড ইস্যু করা হবে। মৌখিক পরীক্ষায় অংশগ্রহণকালে প্রার্থীর জীবন বৃত্তান্তে উল্লেখ করা তথ্যের প্রমাণক হিসেবে সকল মূল সনদপত্র, জাতীয় পরিচয়পত্র এবং ওয়ার্ড কাউন্সিলর/চেয়ারম্যান/মেয়র কর্তৃক ইস্যুকৃত নাগরিকত্বের প্রত্যয়নপত্র সঙ্গে আনতে হবে। মৌখিক পরীক্ষায় অংশগ্রহণের জন্য প্রার্থীগণকে কোনো প্রকার আর্থিক সুবিধা প্রদান করা হবেনা।</li>\r\n</ul>\r\n', 1, '2023-09-21 18:03:00', 1, '2023-09-21 18:12:00', 1);
INSERT INTO `recruitment_committee` (`rc_id`, `rc_title`, `rc_details`, `rc_status`, `rc_created_at`, `rc_created_by`, `rc_updated_at`, `rc_updated_by`) VALUES
(12, 'নিয়োগ/২০২৩', 'স্বারক নং-স.ব্য.ক.কা ১৬(০৮)।২২-২৩.০৬.১১.২০২২,\r\nতারিখঃ ০৬.১১.২০২২। \r\n\r\nসমিতির ব্যবস্থাপনা কমিটির ২২.১০.২০২২ তারিখের সভার সিদ্ধান্ত অনুযায়ী এবং সার্ভিস রুলের ধারা ০৪ এর আলোকে সমিতির ও প্রাথমিক সমিতির শূন্য পদে নিয়োগের নিমিত্তে নিন্মের নাম ও পদবী অনুযায়ী কমিটি গঠন করা হল। নিয়োগ সম্পাদনের নিমিত্তে নিয়োগ কমিটি প্রয়োজনমত যে কাউকে নিয়োগ কাজে অন্তভুক্ত করতে পারবেন।\r\n\r\nউক্ত কমিটি নিয়োগ কার্যাদি সম্পাদনে কার্যভাতা/সম্মানী, অতিরিক্ত কাজের সম্মানী নির্ধারন পূর্বক নিয়োগ সংক্রান্ত যাবতীয় ব্যয় সমিতি ও প্রাথমিক সমিতির বাজেটে বরাদ্দকৃত অর্থ ব্যয় করতে বলা হল।', 1, '0000-00-00 00:00:00', 1, '0000-00-00 00:00:00', 1),
(13, 'নিয়োগ/2023 এর নিয়োগ কমিটি গঠন। ', 'স্বারক নং-স.ব্য.ক.কা ১৬(০৮)।২২-২৩.০৬.১১.২০২২, তারিখঃ ০৬.১১.২০২২। সমিতির ব্যবস্থাপনা কমিটির ২২.১০.২০২২ তারিখের সভার সিদ্ধান্ত অনুযায়ী এবং সার্ভিস রুলের ধারা ০৪ এর আলোকে সমিতির ও প্রাথমিক সমিতির শূন্য পদে নিয়োগের নিমিত্তে নিন্মের নাম ও পদবী অনুযায়ী কমিটি গঠন করা  হ’ল। নিয়োগ সম্পাদনের নিমিত্তে নিয়োগ কমিটি প্রয়োজনমত যে কাউকে নিয়োগ কাজে অর্ন্তভুক্ত করতে পারবেন। উক্ত কমিটি নিয়োগ কার্যাদি সম্পাদনে কার্যভাতা/সম্মানী, অতিরিক্ত কাজের সম্মানী নির্ধারণ পূর্বক নিয়োগ সংক্রান্ত যাবতীয় ব্যয় সমিতি ও প্রাথমিক সমিতির বাজেটে বরাদ্দকৃত অর্থ হতে ব্যয় করতে বলা  হ‘ল।', 1, '0000-00-00 00:00:00', 1, '2023-02-20 13:29:00', 1),
(16, 'vbxcv', 'xcvxcv', 2, '2023-02-20 13:23:00', 1, '2023-02-20 13:30:00', 1),
