INSERT INTO `tbl_breking_news` (`id`, `news`, `status`, `description`, `created_at`) VALUES
(52, 'শিক্ষিত বেকার সঞ্চয় ও ঋণদান সমবায় সমিতি লি. এর কর্মসংস্থান ও দারিদ্র্য বিমোচন প্রকল্পের ব্যবস্থাপকদের উন্নয়ন সভা ০৯.০৩.২০২২ তারিখ বিকাল ০৪ টায় প্রকল্প পরিচালকের কার্যালয়, ওয়্যারলেছ বাজার, চাঁদপুরে অনুষ্ঠিত হয়। সভায় সভাপতিত্ব করেন প্রকল্প পরিচালক মো. জসিম উদ্দিন শেখ এবং প্রধান অতিথি হিসেবে উপস্থিত ছিলেন কেন্দ্রীয় সমিতির ব্যবস্থাপনা পরিচালক মো. আবু তাহের চৌধুরী। এছাড়া কেন্দ্রীয় সমিতি ও প্রাথমিক সমিতির ব্যবস্থাপনা কমিটির নেতৃবৃন্দ এবং সংশ্লিষ্ট প্রতিষ্ঠানগুলোর উর্ধ্বতন কর্মকর্তাগণ এসময় উপস্থিত ছিলেন।', 2, '', '2022-08-27 10:38:23'),
(57, 'শিক্ষিত বেকার সঞ্চয় ও ঋণদান সমবায় সমিতি লি. এর কর্মসংস্থান ও দারিদ্র্য বিমোচন প্রকল্পের ব্যবস্থাপকদের উন্নয়ন সভা ১৯.০৭.২০২২ তারিখ বিকাল ০৪ টায় প্রকল্প পরিচালকের কার্যালয়, ওয়্যারলেছ বাজার, চাঁদপুরে অনুষ্ঠিত হয়। সভায় সভাপতিত্ব করেন প্রকল্প পরিচালক মো. জসিম উদ্দিন শেখ এবং প্রধান অতিথি হিসেবে উপস্থিত ছিলেন কেন্দ্রীয় সমিতির ব্যবস্থাপনা পরিচালক মো. আবু তাহের চৌধুরী। কেন্দ্রীয় সমিতি ও বিভিন্ন প্রাথমিক সমিতির ব্যবস্থাপনা কমিটির নেতৃবৃন্দ এবং সংশ্লিষ্ট প্রতিষ্ঠানগুলোর উর্ধ্বতন কর্মকর্তাগণ এসময় উপস্থিত ছিলেন।', 2, '', '2022-08-27 10:38:23'),
(58, 'ওয়্যারলেছ শিক্ষিত বেকার সঞ্চয় ও ঋণদান সমবায় সমিতি লি. এর ব্যবস্থাপনা কমিটির সভা  ২০.০৭.২০২২ তারিখ বিকাল ০৪ টায় সমিতির কার্যালয়, ওয়্যারলেছ বাজার, চাঁদপুরে অনুষ্ঠিত হয়। সভায় সভাপতিত্ব করেন ব্যবস্থাপনা কমিটির সভাপতি মো. জসিম উদ্দিন শেখ এবং প্রধান অতিথি হিসেবে উপস্থিত ছিলেন কেন্দ্রীয় সমিতির ব্যবস্থাপনা পরিচালক মো. আবু তাহের চৌধুরী। কেন্দ্রীয় সমিতি ও বিভিন্ন সদস্য সমিতির কর্মকর্তাগণ এসময় উপস্থিত ছিলেন।', 2, '', '2022-08-27 10:38:23'),
(59, 'শিক্ষিত বেকার কেন্দ্রীয় সঞ্চয় ও ঋণদান সমবায় সমিতি লি. এর ব্যবস্থাপনা কমিটির সভা  ২১.০৭.২০২২ তারিখ বিকাল ০৪ টায় সমিতির কার্যালয়, ওয়্যারলেছ বাজার, চাঁদপুরে অনুষ্ঠিত হয়। সভায় সভাপতিত্ব করেন ব্যবস্থাপনা কমিটির মো. জসিম উদ্দিন শেখ। সভা পরিচালনা করেন কেন্দ্রীয় সমিতির ব্যবস্থাপনা পরিচালক মো. আবু তাহের চৌধুরী। কেন্দ্রীয় সমিতি ও বিভিন্ন প্রাথমিক সমিতির ব্যবস্থাপনা কমিটির নেতৃবৃন্দ এবং সংশ্লিষ্ট প্রতিষ্ঠানগুলোর উর্ধ্বতন কর্মকর্তাগণ এসময় উপস্থিত ছিলেন।', 2, '', '2022-08-27 10:38:23'),
(60, 'এসবিসিএল ডায়াগনস্টিক সেন্টার এর ব্যবসা উন্নয়ন কমিটির সঙ্গে শিক্ষিত বেকার কেন্দ্রীয় সঞ্চয় ও ঋণদান সমবায় সমিতি লি. এর ব্যবস্থাপনা কমিটির একটি যৌথ সভা  ২১.০৭.২০২২ তারিখ বিকাল ০৬ টায় কেন্দ্রীয় সমিতির কার্যালয়, ওয়্যারলেছ বাজার, চাঁদপুরে অনুষ্ঠিত হয়। সভায় সভাপতিত্ব করেন কেন্দ্রীয় সমিতির ব্যবস্থাপনা কমিটির সভাপতি মো. জসিম উদ্দিন শেখ। সভা পরিচালনা করেন কেন্দ্রীয় সমিতির ব্যবস্থাপনা পরিচালক মো. আবু তাহের চৌধুরী। এসবিসিএল ডায়াগনস্টিক সেন্টার এর ব্যবসা উন্নয়ন কমিটির আহবায়ক ডাঃ সাইফুল ইসলাম সোহেলসহ উন্নয়ন কমিটি ও ব্যবস্থাপনা কমিটির নেতৃবৃন্দ এবং সংশ্লিষ্ট প্রতিষ্ঠানগুলোর উর্ধ্বতন কর্মকর্তাগণ এসময় উপস্থিত ছিলেন।', 2, '', '2022-08-27 10:38:23'),
(61, 'বাংলাদেশ সমবায় একাডেমি, কোটবাড়ীতে প্রশিক্ষণরত ২৫ সদস্যের উপজেলা সমবায় অফিসারের একটি দল তাদের মাঠ সফর কর্মসূচির অংশ হিসেবে ০২.০৮.২০২২ তারিখ চান্দ্রা শিক্ষিত বেকার যুব বহুমূখী সমবায় সমিতি ও এসবিসিএল কেন্দ্রীয় সঞ্চয় ও ঋণদান সমবায় সমিতি ভিজিট করেন। এই মাঠ সফর কর্মসূচীতে প্রশিক্ষণ দলটির নেতৃত্ব দেন বাংলাদেশ সমবায় একাডেমির সম্মানিত অধ্যক্ষ জনাব অঞ্জন কুমার সরকার। কোর্স পরিচালক ও একাডেমির অধ্যাপক (প্রশাসন) জনাব গিয়াস উদ্দিন এবং জেলা সমবায় অফিসার, চাঁদপুর মুহাম্মদ মুজিবুর রহমান এ সময় উপস্থিত ছিলেন। প্রশিক্ষন দলটি দিনব্যাপী প্রতিষ্ঠানের বিভিন্ন কর্মকাণ্ড পর্যবেক্ষণ করেন। প্রতিষ্ঠানের চেয়ারম্যান জনাব মো. জসিম উদ্দিন শেখ এবং কেন্দ্রীয় সমিতির ব্যবস্থাপনা পরিচালক জনাব মো. আবু তাহের চৌধুরী স্ব স্ব প্রতিষ্ঠানের কর্মকাণ্ড তুলে ধরেন।', 2, '', '2022-08-27 10:38:23'),
(64, 'শিক্ষিত বেকার সঞ্চয় ও ঋণদান সমবায় সমিতি লি. এর ব্যবস্থাপনা কমিটির সভা ১১.১০.২০২২ তারিখ মঙ্গলবার সকাল ১১.০০ মিনিটে ওয়্যারলেছ বাজার, চাঁদপুরে অবস্থিত সমিতির কার্যালয়ে অনুষ্ঠিত হয়। সভায় সভাপতিত্ব করেন কেন্দ্রীয় সমিতির ব্যবস্থাপনা পরিচালক মো. আবু তাহের চৌধুরী। সভা পরিচালনা করেন ব্যবস্থাপনা কমিটির সভাপতি মো. জসিম উদ্দিন শেখ। ব্যবস্থাপনা কমিটির অন্যান্য নেতৃবৃন্দ এ সময় উপস্থিত ছিলেন।', 2, '<p style=\"text-align:center\"><img alt=\"\" src=\"https://sbcl.coop/assets/uploads/gallery/1665652596_filename.jpg\" style=\"height:190px; width:300px\" />&nbsp;<img alt=\"\" src=\"https://sbcl.coop/assets/uploads/gallery/1665652477_filename.jpg\" style=\"height:190px; width:300px\" />&nbsp;<img alt=\"\" src=\"https://sbcl.coop/assets/uploads/gallery/1665652450_filename.jpg\" style=\"height:190px; width:300px\" /></p>\r\n', '2022-10-13 09:19:21'),
(65, 'শিক্ষিত বেকার সঞ্চয় ও ঋণদান সমবায় সমিতি লি. এর কর্মসংস্থান ও দারিদ্র্য বিমোচন প্রকল্পের “উন্নয়ন সভা” ১১.১০.২০২২ তারিখ মঙ্গলবার বিকাল ০৩.০০ মিনিটে ওয়্যারলেছ বাজার, চাঁদপুরে অবস্থিত প্রকল্প পরিচালকের কার্যালয়ে অনুষ্ঠিত হয়। সভায় সভাপতিত্ব করেন কেন্দ্রীয় সমিতির ব্যবস্থাপনা পরিচালক মো. আবু তাহের চৌধুরী। প্রকল্প পরিচালক জনাব মোহাম্মদ জসিম উদ্দিন, প্রকল্পের অন্যান্য পরিচালকবৃন্দ ও ঊর্ধ্বতন কর্মকর্তাসহ প্রকল্পভূক্ত সকল সমিতির ব্যবস্থাপকগণ এসময় উপস্থিত ছিলেন।', 2, '<p style=\"text-align: center;\"><img alt=\"????????????? ????????? ?????? ??? ??.??.????\" src=\"https://sbcl.coop/assets/uploads/gallery/1665653604_filename.jpg\" style=\"height:190px; width:300px\" />&nbsp;<img alt=\"????????????? ????????? ?????? ??? ??.??.????\" src=\"https://sbcl.coop/assets/uploads/gallery/1665653548_filename.jpg\" style=\"height:190px; width:300px\" />&nbsp;<img alt=\"????????????? ????????? ?????? ??? ??.??.????\" src=\"https://sbcl.coop/assets/uploads/gallery/1665653537_filename.jpg\" style=\"height:190px; width:300px\" /></p>\r\n', '2022-10-13 09:35:49'),
(66, 'শিক্ষিত বেকার কেন্দ্রীয় সঞ্চয় ও ঋণদান সমবায় সমিতি লি. এর ব্যবস্থাপনা কমিটির সভা ২২.১০.২০২২ তারিখ শনিবার বিকাল ৩.০০ টায় ওয়্যারলেছ বাজার, চাঁদপুরে অবস্থিত সমিতির কার্যালয়ে অনুষ্ঠিত হয়। সভায় সভাপতিত্ব করেন কেন্দ্রীয় সমিতির সভাপতি মো. জসিম উদ্দিন শেখ। সভা পরিচালনা করেন কেন্দ্রীয় সমিতির ব্যবস্থাপনা পরিচালক মো. আবু তাহের চৌধুরী। ব্যবস্থাপনা কমিটির নেতৃবৃন্দসহ সংশ্লিষ্ট কর্মকর্তাগন এ সময় উপস্থিত ছিলেন।', 2, '<p style=\"text-align:center\"><img alt=\"????????? ?????? ??????????? ?????? ??? ??? ??.??.????\" src=\"https://sbcl.coop/assets/uploads/gallery/1666497594_filename.jpg\" style=\"height:190px; width:300px\" />&nbsp;<img alt=\"????????? ?????? ??????????? ?????? ??? ??? ??.??.????\" src=\"https://sbcl.coop/assets/uploads/gallery/1666497569_filename.jpg\" style=\"height:190px; width:300px\" /></p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"\" src=\"https://sbcl.coop/assets/uploads/gallery/1666497617_filename.jpg\" style=\"height:190px; width:300px\" />&nbsp;<img alt=\"????????? ?????? ??????????? ?????? ??? ??? ??.??.????\" src=\"https://sbcl.coop/assets/uploads/gallery/1666497581_filename.jpg\" style=\"height:190px; width:300px\" /></p>\r\n', '2022-10-23 03:18:59'),
(67, 'চান্দ্রা শিক্ষিত বেকার যুব বহুমূখী সমবায় সমিতি লি. এর ব্যবস্থাপনা কমিটির সভা ২২.১০.২০২২ তারিখ শনিবার বিকাল ৫.০০ টায় চান্দ্রা বাজার, ফরিদগঞ্জে অবস্থিত সমিতির নিজস্ব কার্যালয়ে অনুষ্ঠিত হয়। সভায় সভাপতিত্ব করেন সমিতির সভাপতি মো. জসিম উদ্দিন শেখ। সভায় প্রধান অতিথি হিসেবে উপস্থিত ছিলেন সমিতির ব্যবস্থাপনা পরিচালক মো. আবু তাহের চৌধুরী। ব্যবস্থাপনা কমিটির নেতৃবৃন্দসহ সংশ্লিষ্ট কর্মকর্তাগন এ সময় উপস্থিত ছিলেন।', 2, '', '2022-10-23 04:35:10'),
(69, '১৪.১১.২০২২ তারিখে প্রকাশিত নিয়োগ বিজ্ঞপ্তি এবং ১৫, ১৬, ১৭ ডিসেম্বর, ২০২২ তারিখে অনুষ্ঠিত ইন্টারভিউ পরিক্ষার চূড়ান্ত ফলাফলের ভিত্তিতে নির্বাচিত প্রার্থীদের আনুষ্ঠানিক নিয়োগ পত্র প্রদান।', 2, '<p style=\"text-align: center;\"><img alt=\"????? ???? ??????\" src=\"https://sbcl.coop/assets/uploads/gallery/1671703111_filename.jpg\" style=\"height:191px; width:300px\" />&nbsp;<img alt=\"????? ???? ??????\" src=\"https://sbcl.coop/assets/uploads/gallery/1671703123_filename.jpg\" style=\"height:191px; width:300px\" /></p>\r\n\r\n<p style=\"text-align: center;\"><img alt=\"????? ???? ??????\" src=\"https://sbcl.coop/assets/uploads/gallery/1671703134_filename.jpg\" style=\"height:191px; width:300px\" />&nbsp;<img alt=\"????? ???? ??????\" src=\"https://sbcl.coop/assets/uploads/gallery/1671703144_filename.jpg\" style=\"height:191px; width:300px\" /></p>\r\n', '2022-12-22 09:36:49'),
(70, 'শিক্ষিত বেকার কেন্দ্রীয় সঞ্চয় ও ঋণদান সমবায় সমিতি লি. এর ব্যবস্থাপনা কমিটির সভা ১৮.০১.২০২৩ তারিখ বুধবার বিকাল ২.৩০ টায় ওয়্যারলেছ বাজার, চাঁদপুরে অবস্থিত সমিতির কার্যালয়ে অনুষ্ঠিত হয়। সভায় সভাপতিত্ব করেন কেন্দ্রীয় সমিতির সভাপতি মোঃ জসিম উদ্দিন শেখ। ব্যবস্থাপনা কমিটির নেতৃবৃন্দসহ সংশ্লিষ্ট কর্মকর্তাগণ এ সময় উপস্থিত ছিলেন।', 2, '<p style=\"text-align: center;\"><img alt=\"??????????? ?????? ??? ???\" src=\"https://sbcl.coop/assets/uploads/gallery/1674042384_file.jpg\" style=\"height:185px; width:301px\" />&nbsp;<img alt=\"??????????? ?????? ??? ???\" src=\"https://sbcl.coop/assets/uploads/gallery/1674042384_file1.jpg\" style=\"height:205px; width:300px\" />&nbsp;<img alt=\"??????????? ?????? ??? ???\" src=\"https://sbcl.coop/assets/uploads/gallery/1674042384_file2.jpg\" style=\"height:190px; width:300px\" /></p>\r\n', '2023-01-18 11:37:34'),
(71, 'শিক্ষিত বেকার সঞ্চয় ও ঋণদান সমবায় সমিতি লি. এর কর্মসংস্থান ও দারিদ্র্য বিমোচন প্রকল্পের \"উন্নয়ন সভা\" ১৮.০১.২০২৩ তারিখ বুধবার সকাল ১০.০০ টায় ওয়্যারলেছ বাজার, চাঁদপুরে অবস্থিত প্রকল্প পরিচালকের কার্যালয়ে অনুষ্ঠিত হয়। সভায় সভাপতিত্ব করেন প্রকল্প পরিচালক মোহাম্মদ জসিম উদ্দিন। এছাড়াও প্রকল্পের অন্যান্য পরিচালকবৃন্দ ও উর্ধ্বতন কর্মকর্তাসহ প্রকল্পভূক্ত সকল সমিতির ব্যবস্থাপকগণ এসময় উপস্থিত ছিলেন।', 2, '<p style=\"text-align: center;\"><img alt=\"????????????? ?????? ??? ??.??.????\" src=\"https://sbcl.coop/assets/uploads/gallery/1674103383_file.JPG\" style=\"height:194px; width:300px\" />&nbsp;<img alt=\"????????????? ?????? ??? ??.??.????\" src=\"https://sbcl.coop/assets/uploads/gallery/1674103383_file1.JPG\" style=\"height:201px; width:300px\" />&nbsp;<img alt=\"????????????? ?????? ??? ??.??.????\" src=\"https://sbcl.coop/assets/uploads/gallery/1674103383_file2.JPG\" style=\"height:197px; width:299px\" /></p>\r\n', '2023-01-19 04:15:22'),
(72, 'চান্দ্রা শিক্ষিত বেকার যুব বহুমূখী সমবায় সমিতি লি. এর ব্যবস্থাপনা কমিটির সভা ১৫.০১.২০২৩ তারিখ রবিবার বিকাল ০৩.০০ টায় চান্দ্রা বাজারে অবস্থিত সমিতির নিজস্ব কার্যালয়ে (সমিতি ভবনের ৪র্থ তলায়) অনুষ্ঠিত হয়। সভায় সভাপতিত্ব করেন সমিতির সভাপতি মো. জসিম উদ্দিন শেখ। ব্যবস্থাপনা কমিটির নেতৃবৃন্দসহ সংশ্লিষ্ট কর্মকর্তাগণ এ সময় উপস্থিত ছিলেন।', 2, '', '2023-01-19 04:48:00'),
