INSERT INTO `vpresidentpic` (`id`, `title`, `time`, `image`, `description`) VALUES
(2, 'মোঃ আবু তাহের চৌধুরী', '০৭.০১.২০২১ ইং- চলমান', '1662013884_filename.jpg', '<p style=\"text-align: justify;\"><span style=\"color:rgb(85, 85, 85); font-family:adorsholipi,arial,sans-serif; font-size:14px\">বাংলাদেশ সিভিল সার্ভিস ৯ম ব্যাচ&nbsp;এর সমবায় ক্যাডারের প্রাক্তন&nbsp;সদস্য মোঃ আবু তাহের চৌধুরী ০১ জুলাই, ২০২১&nbsp;তারিখে ব্যবস্থাপনা পরিচালক ও প্রধান নির্বাহী অফিসার হিসেবে যোগদান করেন। তিনি ৩০ বছরের বেশী সময় সরকারি ও বেসরকারি বিভিন্ন প্রতিষ্ঠানে নির্বাহী হিসেবে কাজ করেন। তিনি সমবায় অধিদপ্তরের মাঠ পর্যায়ের একাধিক বিভাগসহ প্রধান কার্যালয়ের বিভিন্ন বিভাগের&nbsp;প্রধান&nbsp;হিসেবে দায়িত্ব পালন করেন।এছাড়াও&nbsp;তিনি প্রেষনে বাংলাদেশ সমবায় ব্যাংক লিঃ এর মানব সম্পদ বিভাগের প্রধান এবং বাংলাদেশ ন্যাশনাল ফিসারম্যান কোঅপারেটিভ সোসাইটি লিঃ এর জেনারেল ম্যনেজার ও সিইও হিসেবে দায়িত্ব পালন করেছেন।&nbsp;</span><br />\r\n<span style=\"color:rgb(85, 85, 85); font-family:adorsholipi,arial,sans-serif; font-size:14px\">তিনি ঢাকা বিশ্ববিদ্যালয় হতে ফিনান্স-এ অনার্সসহ ব্যাচেলর এবং ব্যাংকিং মেজরসহ এমবিএ সম্পন্ন করেছেন। তিনি বাংলাদেশ লোকপ্রশাসন প্রশিক্ষণ কেন্দ্র, পরিকল্পনা ও উন্নয়ন একাডেমী, ফিনান্সিয়াল ম্যানেজমেন্ট একাডেমী, বাংলাদেশ ব্যাংক ট্রেনিং একাডেমী, বাংলাদেশ সমবায় একাডেমী, বাংলাদেশ পল্লী উন্নয়ন একাডেমীসহ মার্কিন যুক্তরাষ্ট্র, কানাডা, জাপান, দঃ কোরিয়া, থাইল্যান্ড, মালয়েশিয়া, ইন্দোনেশিয়া, ভারত, শ্রীলংকা ও নেপাল হতে আইন, জন প্রশাসন, আর্থিক ব্যবস্থাপনা, প্রকল্প ব্যবস্থাপনা, সমবায় ব্যবস্থাপনা, মাইক্রো ফাইনান্স ব্যবস্থাপনা, ক্রেডিট ইউনিয়ন ব্যবস্থাপনাসহ বিভিন্ন বিষয়ে উচ্চতর পেশাগত প্রশিক্ষণ কোর্স&nbsp; সম্পন্ন করেছেন।</span><br />\r\n<span style=\"color:rgb(85, 85, 85); font-family:adorsholipi,arial,sans-serif; font-size:14px\">তিনি বাংলাদেশ সিভিল সার্ভিস ৯ম ব্যাচ ফোরাম এর সহ-সভাপতি ও মহাসচিব এবং&nbsp;বিসিএস (সমবায়) এসোসিয়েশনের মহাসচিব হিসেবে একাধিক বার দায়িত্ব পালন করেন। তিনি অফিসার্স ক্লাব ঢাকা, আর্মি গলফ ক্লাব, কুমিল্লা ক্লাবসহ বিভিন্ন&nbsp; পেশাজীবি ও সামাজিক সংগঠনের সাথে সম্পৃক্ত।তিনি বিবাহিত ও দু&rsquo;সন্তানের জনক।</span></p>\r\n');
