(211, 'সমিতির উদ্দেশ্য ও মূল কার্যক্রম', '26319', 'custom', -1, '<h3>সমিতির উদ্দেশ্য ও মূল কার্যক্রম</h3>\r\n\r\n<ul>\r\n	<li><a href=\"http://localhost/sbcl/\">আর্থ-সামাজিক উন্নয়ন</a></li>\r\n	<li><a href=\"http://localhost/sbcl/\">কর্মসংস্থান সৃষ্টি</a></li>\r\n	<li><a href=\"http://localhost/sbcl/\">উদ্যোক্তা তৈরি</a></li>\r\n	<li><a href=\"http://localhost/sbcl/\">কিস্তিতে পণ্য বিক্রয়</a></li>\r\n	<li><a href=\"http://localhost/sbcl/\">স্বনির্ভরতা অর্জন</a></li>\r\n	<li><a href=\"http://localhost/sbcl/\">দারিদ্র বিমোচন</a></li>\r\n	<li><a href=\"http://localhost/sbcl/\">উৎপাদন ও বিপণন</a></li>\r\n	<li><a href=\"http://localhost/sbcl/\">সামাজিক কর্মকাণ্ড</a></li>\r\n</ul>', 'ok', 'OK', '2023-01-25 06:11:45', 0),
(212, 'সহযোগী প্রতিষ্ঠান', '78500', 'custom', -1, '<ol>\r\n	<li><a href=\"#\">শিক্ষিত বেকার কো-অপারেটিভ লিমিটেড</a></li>\r\n	<li><a href=\"#\">কর্মসংস্থান ও দারিদ্র্য বিমোচন প্রকল্প</a></li>\r\n	<li><a href=\"#\">এসবিসিএল ডায়াগনস্টিক সেন্টার</a></li>\r\n	<li><a href=\"#\">এসবিসিএল হাউজিং লিমিটেড</a></li>\r\n	<li><a href=\"#\">এসবিসিএল আমাদের পণ্য আমাদের বাজার লিমিটেড</a></li>\r\n	<li><a href=\"#\">এসবিসিএল প্রবাসী আবাস</a>&nbsp;(প্রস্তাবিত)</li>\r\n	<li><a href=\"#\">এসবিসিএল স্কুল এন্ড কলেজ</a>&nbsp;(প্রস্তাবিত)</li>\r\n	<li><a href=\"#\">এসবিসিএল আউটসোর্সিং ইনিস্টিটিউট</a>&nbsp;(প্রস্তাবিত)</li>\r\n	<li><a href=\"#\">এসবিসিএল পরিবহন</a>&nbsp;(প্রস্তাবিত)</li>\r\n</ol>', 'ok', 'OK', '2022-09-03 09:19:57', 0),
(213, 'ব্যবস্থাপনা পদ্ধতি', '93511', 'custom', -1, '<h3>ব্যবস্থাপনা পদ্ধতি</h3>\r\n\r\n<ul>\r\n <li><a href=\"http://localhost/sbcl/\">বার্ষিক সাধারণ সভা অনুষ্ঠান (সকল)</a></li>\r\n <li><a href=\"http://localhost/sbcl/\">লভ্যাংশ প্রদান (বছর ভিত্তিক)</a></li>\r\n <li><a href=\"http://localhost/sbcl/\">বাজেট বাস্তবায়নের হার (বছর ভিত্তিক)</a></li>\r\n <li><a href=\"http://localhost/sbcl/\">আর্থিক প্রবৃদ্ধির হার (বছর ভিত্তিক)</a></li>\r\n <li><a href=\"http://localhost/sbcl/\">ব্যবস্থাপনা কমিটির নির্বাচন (সকল)</a></li>\r\n <li><a href=\"http://localhost/sbcl/\">অডিট ফি পরিশোধ (বছর ভিত্তিক)</a></li>\r\n <li><a href=\"http://localhost/sbcl/\">সিডিএফ প্রধান (বছর ভিত্তিক)</a></li>\r\n <li><a href=\"http://localhost/sbcl/\">বার্ষিক নীট লাভ (বছর ভিত্তিক)</a></li>\r\n <li><a href=\"http://localhost/sbcl/\">বার্ষিক নীট লাভ (বছর ভিত্তিক)</a></li>\r\n <li><a href=\"http://localhost/sbcl/\">বিনিয়োগ খেলাপির হার (বছর ভিত্তিক)</a></li>\r\n <li><a href=\"http://localhost/sbcl/\">বার্ষিক তারল্য তহবিল (বছর ভিত্তিক)</a></li>\r\n</ul>', 'ok', 'OK', '2021-05-12 11:34:34', 0),
(214, 'সামাজিক কর্মকাণ্ডের চিত্র', '80274', 'custom', -1, '<h3>সামাজিক কর্মকাণ্ডের চিত্র</h3>\r\n\r\n<ul>\r\n <li><a href=\"http://localhost/sbcl/\">করোনাকালীন সহযোগিতার চিত্র</a></li>\r\n <li><a href=\"http://localhost/sbcl/\">দরিদ্র সন্তানের লেখাপড়ায় আর্থিক সহায়তা</a></li>\r\n <li><a href=\"http://localhost/sbcl/\">দরিদ্র কন্যাসন্তানের বিবাহে আর্থিক সহায়তা</a></li>\r\n <li><a href=\"http://localhost/sbcl/\">ধর্মীয় প্রতিষ্ঠানে আর্থিক সহায়তা</a></li>\r\n <li><a href=\"http://localhost/sbcl/\">দরিদ্র ও দুস্থদের চিকিৎসায় আর্থিক সহায়তা</a></li>\r\n <li><a href=\"http://localhost/sbcl/\">দরিদ্র পরিবারের গৃহনির্মাণে আর্থিক সহায়তা</a></li>\r\n <li><a href=\"http://localhost/sbcl/\">শিক্ষা প্রতিষ্ঠানে আর্থিক সহায়তা</a></li>\r\n <li><a href=\"http://localhost/sbcl/\">সংস্কৃতি কর্মীদের আর্থিক সহায়তা</a></li>\r\n <li><a href=\"http://localhost/sbcl/\">প্রাকৃতিক দুর্যোগে খাদ্য সহায়তা</a></li>\r\n <li><a href=\"http://localhost/sbcl/\">প্রাথমিক শিক্ষা বৃত্তি প্রকল্প</a></li>\r\n</ul>', 'ok', 'OK', '2021-05-12 11:34:58', 0),
(215, 'কর্মকর্তা-কর্মচারি', '25608', 'custom', -1, '<h3>কর্মকর্তা-কর্মচারি</h3>\n\n<ul>\n <li><a href=\"http://localhost/sbcl/\">নিয়োগ বিজ্ঞপ্তি</a></li>\n <li><a href=\"http://localhost/sbcl/\">নিয়োগ পরীক্ষা</a></li>\n <li><a href=\"http://localhost/sbcl/\">নিয়োগ ফলাফল</a></li>\n <li><a href=\"http://localhost/sbcl/\">স্টাফ প্রশিক্ষণ</a></li>\n <li><a href=\"http://localhost/sbcl/\">স্টাফ নিয়ন্ত্রণ</a></li>\n <li><a href=\"http://localhost/sbcl/\">স্টাফ কল্যাণ তহবিল</a></li>\n <li><a href=\"http://localhost/sbcl/\">স্টাফ পিকনিক বা বিনোদন</a></li>\n <li><a href=\"http://localhost/sbcl/\">স্টাফ অবসর ওয়েল ফেয়ার</a></li>\n <li><a href=\"http://localhost/sbcl/\">স্টাফ&nbsp;পেনশন পরিষদ</a></li>\n <li><a href=\"http://localhost/sbcl/\">স্টাফ</a>&nbsp;লিষ্ট</li>\n</ul>', 'ok', 'OK', '2022-01-18 14:53:30', 0),
(216, 'সমবায় সমিতি আইন', '90931', 'custom', 209, '<table align=\"center\" border=\"2\" cellpadding=\"0\" cellspacing=\"0\">\r\n	<tbody>\r\n		<tr>\r\n			<td colspan=\"3\" style=\"text-align: center;\">সমবায় সমিতি পরিচালনায় সমবায় আইন অনুযায়ী পরিচালনা পদ্ধতি</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"text-align: center;\">ক্রমিক নং</td>\r\n			<td>\r\n			<p style=\"text-align: center;\">প্রয়োগকৃত বিষয়</p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\">প্রয়োগকৃত সমবায় সমিতি আইন/০১ (সংশোধিত-০২, ১৩) এর ধারা</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"text-align: center;\">০১</td>\r\n			<td style=\"text-align: center;\">শেয়ার মূলধন ও শেয়ার সদস্যদের দায়-দায়িত্ব</td>\r\n			<td style=\"text-align: center;\">১৫ (১) ধারা অনুযায়ী সদস্যগণ দায়-দায়িত্ব সম্পর্কে অবগত আছেন।</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p style=\"text-align: center;\">০২</p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\">সাধারণ&nbsp;সভা</p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\">১৭ (১) ধারা মতে বিশেষ সাধারণ সভা অনুষ্ঠিত হয় এবং বার্ষিক নিরীক্ষা কার্যক্রম সম্পন্ন করার পর ১৭ (৩) ধারা, ১৭ (৪) ধারা এবং ১৭ (৫) ধারা অনুসরন করে, ২০২০-২০২১ অর্থ বছরের বার্ষিক সাধারণ সভা অনুষ্ঠিত হয়।</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p style=\"text-align: center;\">০৩</p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\">নির্বাচন</p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\">সমিতি যথাসময়ে ১৮ (৪) ধারা, ১৮ (৮) ধারা এবং ১৯ (১) ধারা সমূহ অনুসরণ করে ব্যবস্থাপনা কমিটির নির্বাচন অনুষ্ঠান হয়।</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p style=\"text-align: center;\">০৪</p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\">রেজিষ্টার সমূহ</p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\">২৪ ধারা অনুযায়ী সমিতির প্রয়োজনীয় বহি ও রেজিষ্টার হালনাগাদ সংরক্ষন আছে।</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p style=\"text-align: center;\">০৫</p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\">আমানত ও ঋণ প্রদান</p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\">২৬ (১) (২) ধারা অনুসরণ করে সমিতির আর্থিক কার্যক্রম পরিচালনা করা হয়।</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p style=\"text-align: center;\">০৬</p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\">সমিতির তহবিল বিনিয়োগ</p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\">৩৩ (ক) (খ) (গ) ধারা অনুসরণ করে তহবিল লাভজনক খাতে বিনিয়োগ করা হয়।</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p style=\"text-align: center;\">০৭</p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\">মুনাফা বিনিয়োগ ও বন্টন</p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\">প্রতি সমবায় বর্ষে ৩৪ (১) (২) (৩) ধারা মতে সমিতির নীট লাভ/মুনাফা বন্টন করা হয়। সংরক্ষিত তহবিল ও কু-ঋণ তহবিলের অর্থ ৩৪ (২) (৩) ধারা মতে বিভিন্ন আর্থিক প্রতিষ্ঠানে বিনিয়োগ করা আছে।</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p style=\"text-align: center;\">০৮</p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\">সদস্যদের ভোট এবং অধিকার প্রয়োগ</p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\">৩৬ ধারা মতে সদস্যদের ভোট এবং ৩৭ ধারা মতে সদস্যগণ অধিকার প্রয়োগে সচেষ্ট আছে।</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p style=\"text-align: center;\">০৯</p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\">গ্রহীতা মনোনয়ন</p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\">সমিতির সদস্য অর্ন্তভুক্ত হলে ৪০ ধারা অনুযায়ী উক্ত সদস্যের একজন একক ব্যক্তি মনোনীত থাকবেন, যাহা চলমান আছে।</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p style=\"text-align: center;\">১০</p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\">নিরীক্ষা প্রতিবেদন</p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\">৪৬ ধারা অনুযায়ী নিরীক্ষক নিরীক্ষা কার্যক্রম সম্পাদন করেন এবং যথাসময়ে নিরীক্ষা প্রতিবেদন দাখিল করেন।</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p style=\"text-align: center;\">১১</p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\">অডিটে দোষ-ক্রটি সংশোধন</p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\">নিরীক্ষা প্রতিবেদনের উপর দোষ-ত্রুটি সংশোধন পূর্বক ৪৭ ধারা অনুযায়ী অডিট সংশোধনী ব্যবস্থাপনা কমিটি, সমিতির নিবন্ধন কর্তৃপক্ষের নিকট যথাসময়ে দাখিল করেন।</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p style=\"text-align: center;\">১২</p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\">তদন্ত</p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\">এ যাবত ৪৯ ধারা তদন্তের কোন প্রয়োজন হয় নাই।</p>\r\n			</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n\r\n<div>&nbsp;</div>', 'ok', 'OK', '2022-08-14 06:43:25', 0),
(217, 'সমবায় সমিতি বিধিমালা', '22838', 'custom', 209, '<table align=\"center\" border=\"2\" cellpadding=\"0\" cellspacing=\"0\">\n <tbody>\n  <tr>\n   <td colspan=\"3\">\n   <p>সমবায় সমিতি পরিচালনায় সমবায় বিধিমালা অনুযায়ী পরিচালনা পদ্ধতি</p>\n   </td>\n  </tr>\n  <tr>\n   <td>\n   <p>ক্রমিক নং</p>\n   </td>\n   <td>\n   <p>প্রয়োগকৃত বিষয়</p>\n   </td>\n   <td>\n   <p>প্রয়োগকৃত সমবায় সমিতি বিধিমালা/২০০৪ ইং</p>\n   </td>\n  </tr>\n  <tr>\n   <td>\n   <p>০১</p>\n   </td>\n   <td>\n   <p>উপ-আইন প্রণয়ন&nbsp;</p>\n   </td>\n   <td>\n   <p>৮ (১) (২) বিধিমতে সমিতির উপ-আইন প্রণীত ও নিবন্ধিত।</p>\n   </td>\n  </tr>\n  <tr>\n   <td>\n   <p>০২</p>\n   </td>\n   <td>\n   <p>সদস্যভুক্তি, বহিষ্কার কিংবা অপসারণ</p>\n   </td>\n   <td>\n   <p>১০ ও ১১ বিধির আলোকে সদস্য ভর্তি করা হয় এবং উপ-আইনের যোগ্যতা হারালে সদস্য পদ বহিষ্কার কিংবা অপসারণ করা হয়।</p>\n   </td>\n  </tr>\n  <tr>\n   <td>\n   <p>০৩</p>\n   </td>\n   <td>\n   <p>সাধারণ সভা</p>\n   </td>\n   <td>\n   <p>সমিতিতে দু&rsquo;ধরনের সাধারণ সভা অনুষ্ঠিত হয়। সমিতি ১৪ বিধি, ১৬ বিধি অনুসরণ পূর্বক নিয়মিত সাধারণ সভা অনুষ্ঠান হয়। উহার ছায়ালিপি ১৯ (২) বিধি মতে নিবন্ধকের নিকট দাখিল নিশ্চিত করা হয়।</p>\n   </td>\n  </tr>\n  <tr>\n   <td>\n   <p>০৪</p>\n   </td>\n   <td>\n   <p>নির্বাচন</p>\n   </td>\n   <td>\n   <p>ব্যবস্থাপনা কমিটি, নির্বাচনে ১৪ (৩) (৪), ২৪, ২৬ (২) এবং ২৭ (১) বিধি অনুসরণ পূর্বক ৩৪ (৫) বিধি মতে নির্বাচনী ফলাফল প্রকাশের মাধ্যমে গঠন করা হয়।</p>\n   </td>\n  </tr>\n  <tr>\n   <td>\n   <p>০৫</p>\n   </td>\n   <td>\n   <p>ব্যবস্থাপনা কমিটি সভা</p>\n   </td>\n   <td>\n   <p>ব্যবস্থাপনা কমিটির সভায় ৪১, ৪২ এবং ৪৪ বিধি অনুসরণ পূর্বক নিয়মিত সভা অনুষ্ঠিত হয়।</p>\n   </td>\n  </tr>\n  <tr>\n   <td>\n   <p>০৬</p>\n   </td>\n   <td>\n   <p>ব্যবস্থাপনা কমিটির ক্ষমতা, দায়িত্ব ও কার্যবলী</p>\n   </td>\n   <td>\n   <p>সমিতির ব্যবস্থাপনা কমিটি, কার্যক্রম পরিচালনায় ৪৬ বিধিমতে ক্ষমতা এবং ৪৭ বিধিমতে দায়িত্ব ও কার্যবলী বাস্তবায়নে অনুসরণ করা হয়।</p>\n   </td>\n  </tr>\n  <tr>\n   <td>\n   <p>০৭</p>\n   </td>\n   <td>\n   <p>সমিতির রেজিষ্টার ও বহিসমূহ</p>\n   </td>\n   <td>\n   <p>সমিতির নিবন্ধিত কার্যালয়ে ৫৬ বিধি মতে রেজিষ্টার বহিসমূহ সংরক্ষন করা হয়।</p>\n   </td>\n  </tr>\n  <tr>\n   <td>\n   <p>০৮</p>\n   </td>\n   <td>\n   <p>বার্ষিক রির্টান</p>\n   </td>\n   <td>\n   <p>সমবায় বর্ষ সমাপ্তির পর ৫৭ বিধি মতে সমিতির হিসাব বিবরণী নিয়মিতভাবে নিবন্ধক বরাবর প্রেরণ করা হয়।</p>\n   </td>\n  </tr>\n  <tr>\n   <td>\n   <p>০৯</p>\n   </td>\n   <td>\n   <p>ঋণ ও আমানত গ্রহণ</p>\n   </td>\n   <td>\n   <p>বার্ষিক সাধারণ সভায় ৬৪ বিধি মতে সর্বোচ্চ&nbsp;ও আমনত গ্রহণের উর্ধ্বসীমা নির্ধারণ করা হয়।</p>\n   </td>\n  </tr>\n  <tr>\n   <td>\n   <p>১০</p>\n   </td>\n   <td>\n   <p>সমিতির তারল্য</p>\n   </td>\n   <td>\n   <p>সঞ্চয় আমানতের উপর ৬৭ বিধি অনুযায়ী তারল্য যথাযথ ভাবে সংরক্ষণ করা হয়।</p>\n   </td>\n  </tr>\n  <tr>\n   <td>\n   <p>১১</p>\n   </td>\n   <td>\n   <p>সমিতির ঋণ</p>\n   </td>\n   <td>\n   <p>সমিতির ঋণ প্রদানে ৭০, ৭২, ৭৩ এবং ৭৪ (১) বিধি&nbsp; অনুসরণ করা হয়।</p>\n   </td>\n  </tr>\n  <tr>\n   <td>\n   <p>১২</p>\n   </td>\n   <td>\n   <p>তহবিল বিনিয়োগ</p>\n   </td>\n   <td>\n   <p>ব্যবস্থাপনা কমিটি এবং সাধারণ সভায় অনুমোদন সাপেক্ষে ৮০ (খ) বিধি মতে সমিতির অর্থ শেয়ার মার্কেটে বিনিয়োগ করা হয়।</p>\n   </td>\n  </tr>\n  <tr>\n   <td>\n   <p>১৩</p>\n   </td>\n   <td>\n   <p>নীট মুনাফা</p>\n   </td>\n   <td>\n   <p>প্রত্যেক অর্থ-বছরে ৮১ বিধি অনুসরণ করে নীট মুনাফা নির্ধারণ করা হয়।</p>\n   </td>\n  </tr>\n  <tr>\n   <td>\n   <p>১৪</p>\n   </td>\n   <td>\n   <p>সংরক্ষিত তহবিল</p>\n   </td>\n   <td>\n   <p>সমিতির উপ-আইন অনুযায়ী নীট মুনাফার ১৫% সংরক্ষিত তহবিল ৮২ বিধি মতে ব্যবহার করা হয়।</p>\n   </td>\n  </tr>\n  <tr>\n   <td>\n   <p>১৫</p>\n   </td>\n   <td>\n   <p>লভ্যাংশ</p>\n   </td>\n   <td>\n   <p>প্রতি বছর বার্ষিক সাধারণ সভায় ৮৩ বিধি অনুসরণ পূর্বক লভ্যাংশ ঘোষনা করা হয়।</p>\n   </td>\n  </tr>\n  <tr>\n   <td>\n   <p>১৬</p>\n   </td>\n   <td>\n   <p>সমবায় উন্নয়ন তহবিল</p>\n   </td>\n   <td>\n   <p>৮৪ (২) বিধি মতে প্রতি সমবায় বর্ষে নিরীক্ষিত উদ্বৃত্তপত্রের ভিত্তিতে নীট মুনাফা হতে ৩% &ldquo;সমবায় উন্নয়ন তহবিল&rdquo; শিরোনামে যথাযথ হিসাবে নিয়মিত জমা করা হয়।</p>\n   </td>\n  </tr>\n  <tr>\n   <td>\n   <p>১৭</p>\n   </td>\n   <td>\n   <p>ভবিষ্য তহবিল</p>\n   </td>\n   <td>\n   <p>৮৫ বিধি মতে সমিতির&nbsp;কর্মকর্তা/কর্মচারীগণ মূল বেতনের ১০% অর্থ ভবিষ্য তহবিলে জমা করা হয়। যাহা সমিতির সার্ভিস রুলে অর্ন্তভুক্ত। উক্ত তহবিলের উপর ১৫% লাভ প্রদাণ করা হয়।</p>\n   </td>\n  </tr>\n  <tr>\n   <td>\n   <p>১৮</p>\n   </td>\n   <td>\n   <p>মুনাফা বন্টন</p>\n   </td>\n   <td>\n   <p>৮৬ বিধি অনুসরণ করে মুনাফা বন্টন করা হয়।</p>\n   </td>\n  </tr>\n  <tr>\n   <td>\n   <p>১৯</p>\n   </td>\n   <td>\n   <p>ভোট প্রদান ও সদস্যের অধিকার</p>\n   </td>\n   <td>\n   <p>কেন্দ্রীয় সমিতির ভোট প্রদানে ৮৭ (ক) (খ) বিধি এবং প্রাথমিক সমিতির সদস্যগণ অধিকার প্রয়োগে ৮৮ (২) (৩) বিধি অনুসরণ করা হয়।&nbsp;</p>\n   </td>\n  </tr>\n  <tr>\n   <td>\n   <p>২০</p>\n   </td>\n   <td>\n   <p>গ্রহীতা মনোনয়ন বা মনোনীত ব্যক্তি</p>\n   </td>\n   <td>\n   <p>৮৯ বিধি অনুযায়ী প্রাথমিক সমিতি সমূহ, সদস্য ভর্তির সাথে মনোনীত ব্যক্তি অর্ন্তভুক্ত করা হয় এবং মনোনীত সকল ব্যক্তিদের রেজিষ্টার সংরক্ষণ করা হয়।</p>\n   </td>\n  </tr>\n  <tr>\n   <td>\n   <p>২১</p>\n   </td>\n   <td>\n   <p>শেয়ার সর্ম্পকিত সীমাবদ্ধতা</p>\n   </td>\n   <td>\n   <p>৯০ বিধি অনুযায়ী সমিতির উপ-আইনে সদস্যদের শেয়ার দায় সীমিত রাখা হয়েছে।</p>\n   </td>\n  </tr>\n  <tr>\n   <td>\n   <p>২২</p>\n   </td>\n   <td>\n   <p>কু-ঋণ</p>\n   </td>\n   <td>\n   <p>৯৫ বিধি মতে সমিতির কু-ঋণ নির্ধারন করা হয়।</p>\n   </td>\n  </tr>\n  <tr>\n   <td>\n   <p>২৩</p>\n   </td>\n   <td>\n   <p>কু-ঋণ অবলোপন</p>\n   </td>\n   <td>\n   <p>উপ-আইন অনুযায়ী নীট লাভের ১০% কু-ঋণ তহবিল সমিতির উদ্ধৃতপত্রে রাখা হয়। ৯৬ বিধি অনুযায়ী এ যাবত কু-ঋণ তহবিলের টাকা অবলোপন করা হয় নাই।</p>\n   </td>\n  </tr>\n  <tr>\n   <td>\n   <p>২৪</p>\n   </td>\n   <td>\n   <p>নিরীক্ষার তারিখ</p>\n   </td>\n   <td>\n   <p>৯৮ বিধি মতে সমিতির নির্ধারিত সময়ের মধ্যে নিয়মিতভাবে নিরীক্ষা সম্পন্ন করা হয়।</p>\n   </td>\n  </tr>\n  <tr>\n   <td>\n   <p>২৫</p>\n   </td>\n   <td>\n   <p>হিসাব লিপিবদ্ধকরণ</p>\n   </td>\n   <td>\n   <p>৯৯ বিধি মতে সমবায় বর্ষ শেষ হওয়ার নির্ধারিত সময়ের মধ্যে সমিতির হিসাব বিবরণী&nbsp;প্রতিনিয়ত প্রস্তুত করা হয়।</p>\n   </td>\n  </tr>\n  <tr>\n   <td>\n   <p>২৬</p>\n   </td>\n   <td>\n   <p>নিরীক্ষা প্রকৃতি, আর্থিক লেন-দেন যাচাই, নিরীক্ষা পদ্ধতি, প্রতিবেদন ও নিরীক্ষা সংশোধনী</p>\n   </td>\n   <td>\n   <p>সমবায় সমিতির ১০০, ১০১, ১০২, ১০৩ বিধি অনুসরণ পূর্বক নিরীক্ষকগন, নিরীক্ষাকার্য সম্পাদন করেন এবং প্রতিবেদন দাখিল করেন। ১০৪ (১) বিধি মতে নিরীক্ষা প্রতিবেদনে উল্লেখিত ভুল ও অনিয়ম সমূহ সংশোধন পূর্বক নির্ধারিত সময়ে সংশোধিত প্রতিবেদন নিবন্ধন কর্তৃপক্ষের বরাবরে প্রতিনিয়ত দাখিল করা হয়।</p>\n   </td>\n  </tr>\n  <tr>\n   <td>\n   <p>২৭</p>\n   </td>\n   <td>\n   <p>নিরীক্ষা ফি নির্ধারন ও পরিশোধ</p>\n   </td>\n   <td>\n   <p>১০৭ বিধি অনুযায়ী সমিতির নিরীক্ষা ফি নির্ধারন করা হয়। এবং ১০৮ বিধি অনুযায়ী নির্ধারিত কোডে ট্রেজারি চালানের মাধ্যমে জমা করা হয়।</p>\n   </td>\n  </tr>\n  <tr>\n   <td>\n   <p>২৮</p>\n   </td>\n   <td>\n   <p>সমিতি পরিদর্শন</p>\n   </td>\n   <td>\n   <p>১১০ বিধি মতে নিবন্ধক কর্তৃক সমিতি সমূহ পরিদর্শন করা হয়ে থাকে।</p>\n   </td>\n  </tr>\n  <tr>\n   <td>\n   <p>২৯</p>\n   </td>\n   <td>\n   <p>বিরোধ নিষ্পত্তি</p>\n   </td>\n   <td>\n   <p>এ যাবৎ কোন প্রকার বিরোধ নিষ্পত্তির বিষয়ে অভিযোগ উত্থাপিত হয় নাই।</p>\n   </td>\n  </tr>\n </tbody>\n</table>', 'ok', 'OK', '2022-02-22 03:44:59', 0),
(218, 'সমিতির উপ-আইন', '94389', 'custom', 209, '<p>সমিতি পরিচালনায় প্রণীত উপ-আইনে বর্ণিত যে সকল শিরোনামে সমিতি পরিচালিত হয় তা নিন্মরুপ: নাম, সমিতির ঠিকানা, উদ্দেশ্য, সভ্য নিবার্চনি কর্ম এলাকা, সভ্য/সদস্য, সভ্য/সদস্য নিবার্চন, সভ্যের মনোনীত ব্যক্তি, সভ্য পদ ত্যাগ, সভ্যগণের জরিমানা-বহিস্কার বা সাময়িক বহিস্কার-বিতাড়ন ও শেয়ার বাজেয়াপ্ত, সভ্য পদের অবসান, বিতাড়িত বা বহিস্কৃত বা সভ্যপদ ত্যাগীর প্রাপ্য ফেরৎ, দায়-দায়িত্ব, মূলধন, শেয়ার মূলধন, শেয়ারের মূল্য আদায়, শেয়ার সার্টিফিকেট, শেয়ার হস্তান্তর, শেয়ার বাজেয়াপ্ত, ঋণ বা আমানত গ্রহণ, তারল্য তহবিল (ফ্লুইড বা লিকুইড কভার), মূলধন ব্যবহার, অব্যহৃত তহবিল সংরক্ষণ, কর্জ বা বিনিয়োগ প্রদাণ, ঋণ বা বিনিয়োগ মন্জুরের&nbsp;সীমাবদ্ধতা, কর্জ বা বিনিয়োগ গ্রহণযোগ্যতা, কর্জের বা বিনিয়োগের মুনাফা, কর্জের জামিন, কর্জ পরিশোধ, সরবরাহ কার্যক্রম, ব্যবসা পরিচালনা, কর্ম ও কর্মসূচী, সমিতির চূড়ান্ত কর্তৃপক্ষ, বার্ষিক/বিশেষ সাধারণ সভার নোটিশ, বার্ষিক সাধারণ সভা, বিশেষ সাধারণ সভা, সাধারণ সভার সভাপতি, সাধারণ সভার কোরাম, সাধারণ সভার সিদ্ধান্ত গ্রহণ ও ভোটানুষ্ঠান, সাধারণ সভার কার্যবিবরণী, ব্যবস্থাপনা কমিটি, ব্যবস্থাপনা কমিটি গঠন, নিবার্চন কমিটি নিয়োগ, নিবার্চন কমিটির কাযর্ক্রম, নির্বাচিত কমিটির দায়িত্বভার গ্রহণ, ব্যবস্থাপনা কমিটির ক্ষমতা, ব্যবস্থাপনা কমিটির দায়িত্ব ও কার্যবলী, ব্যবস্থাপনা কমিটি সভা, ব্যবস্থাপনা কমিটির সভার কোরাম, ব্যবস্থাপনা কমিটির তলবী সভা, সভাপতি/সহ-সভাপতি/সম্পাদক, সভাপতি ও সহ-সভাপতির ক্ষমতা ও কর্তব্য, সম্পাদক এর ক্ষমতা ও কর্তব্য, প্রকল্প ব্যবস্থাপনা পরিচালক, অভ্যন্তরীণ তত্ত্বাবধান ও হিসাব নিরীক্ষা পদ্ধতি, ব্যবস্থপনা কমিটির সদস্য পদের অপসারণ, ব্যবস্থাপনা কমিটির সদস্য পদের বিলুপ্তি, প্রকল্প পরিচালনা পদ্ধতি, প্রকল্প পরিচালনার কমিটির দায়িত্ব, লাভ বন্টন, সংরক্ষিত কু-ঋণ দাতব্য তহবিল ব্যবহার, লভ্যাংশ (ডিভিডেন্ড প্রদান), সমবায় উন্নয়ন তহবিল, সভ্যগণকে উপ-আইন ও&nbsp;উদ্বৃতপত্র সরবরাহ, খাতাপত্র পরিদর্শন এবং উহার প্রত্যয়ায়িত অনুলিপি সরবরাহ, বিবাদ নিষ্পতি, উপ-আইন প্রণয়ন ও সংশোধনের পদ্ধতি, হিসাব পত্র, সমিতির পক্ষে দলিলাদি স্বাক্ষর করিবার ক্ষমতা, নোটিশ প্রদান বা প্রেরণের পদ্ধতি এবং সাধারণ।</p>', 'ok', 'OK', '2022-02-10 09:40:03', 0),
(219, 'সমিতি কর্তৃক প্রনীত বিভিন্ন নীতিমালা', '84889', 'custom', 209, '<p>প্রাথমিক ও কেন্দ্রীয় সমিতিসহ ১৭টি সমিতির আর্থিক ও ব্যবস্থাপনা কার্যক্রম সুশৃঙ্খল করার জন্য সাধারণ সভার অনুমোদন সাপেক্ষে ব্যবস্থাপনা কমিটি কর্তৃক নিন্মোক্ত নীতিমালাসমূহ প্রণয়ন করা হয়ঃ</p>\r\n\r\n<ul>\r\n <li>সদস্য নীতিমালা</li>\r\n <li>মাসিক সঞ্চয় আমানতের নীতিমালা</li>\r\n <li>অস্থায়ী আমানতের নীতিমালা</li>\r\n <li>স্থায়ী আমানতের নীতিমালা</li>\r\n <li>বিনিয়োগ নীতিমালা</li>\r\n <li>অভ্যন্তরীণ নিরীক্ষা নীতিমালা</li>\r\n <li>কর্মকর্তা-কর্মচারী নিয়োগ ও পদোন্নতি নীতিমালা</li>\r\n <li>ভবিষ্যৎ তহবিল হতে মুনাফা গ্রহণ নীতিমালা</li>\r\n <li>কর্মকর্তা-কর্মচারী কল্যাণ তহবিল নীতিমালা</li>\r\n <li>যানবাহন সুবিধা নীতিমালা</li>\r\n</ul>', 'ok', 'OK', '2022-08-10 09:52:24', 0),
(220, 'স্টাফ সার্ভিস রুল', '23687', 'custom', 209, '<p>সমিতির কার্যাদি সুষ্ঠভাবে পরিচালনার উদ্দেশ্যে সমবায় সমিতি বিধিমালা/২০০৪ এর ৪৬ (৩) বিধিমতে নিয়োগ, সমবায় সমিতি আইন/০১ এর ১৭ (৪) (জ) ধারা মতে সাধারণ সভায় অনুমোদন ক্রমে চাকরির বিধানাবলী/স্টাফ সার্ভিস রুলেঃ&nbsp;সংক্ষিপ্ত শিরোনাম ও প্রয়োগ, সজ্ঞা বা বিষয়, নিয়োগ ও পদোন্নতি, কর্মকর্তা বা কর্মচারিগণের কার্যভাতা এবং বেতন ভাতা নির্ধারনসহ বেতন গ্রেড, ছুটি ইত্যাদি, ভ্রমন ভাতা ইত্যাদি, চাকরির বৃত্তান্ত, শাস্তি প্রদান পদ্ধতি, ভবিষ্য তহবিল ও তহবিল হতে সুবিধা গ্রহণ, অবসর গ্রহণ/চাকরির অবসান ইত্যাদি, পেনশন ও আনুতোষিক নির্ণয়, বিভিন্ন প্রকার ভাতা বা সুবিধা সংক্রান্ত বিষয়াবলী, আর্থিক বিধি বা ফাইনান্সিয়াল রুল, অফিস ব্যবস্থাপনা, বার্ষিক গোপনীয় প্রতিবেদন, চাকরি রেকর্ড এবং বিবিধ বিষয়সমূহ অর্ন্তভুক্ত আছে।</p>', 'ok', 'OK', '2022-02-07 12:22:11', 0),
