(231, 'আর্থ-সামাজিক উন্নয়ন', '98010', 'custom', 211, '<p style=\"text-align: justify;\">প্রাথমিক সমিতি ও কেন্দ্রীয় সমিতিসহ মোট ১৭ (সতেরো) টি সমিতির উদ্দেশ্য সমবায়ের মাধ্যমে বেকারত্ব দূরীকরণ, স্বনির্ভরতা অর্জন, দারিদ্র্য বিমোচন, কর্মসংস্থান সৃষ্টি, আর্থ সামাজিক উন্নয়ন, উদ্যোক্তা সৃষ্টি, সমবায়ের সফলতা বিস্তার এবং সমিতির কার্য পরিধি দ্রুত সম্প্রসারন।</p>\r\n\r\n<p style=\"text-align: justify;\">মূল কার্যক্রমঃ ক্ষুদ্র ক্ষুদ্র সঞ্চয়ের মাধ্যমে তহবিল সৃষ্টি এবং উক্ত তহবিল হতে সদস্যদের মধ্যে পণ্য বিক্রয়, উৎপাদনমূখী খাতে বিনিয়োগ বা ঋণ বিতরণের মাধ্যমে আর্থ সামাজিক উন্নয়ন করা। কর্মসংস্থান সৃষ্টি, দারিদ্র্য বিমোচন, স্বর্নিভরতা অর্জন, এসবিসিএল আমাদের পণ্য আমাদের বাজার কোম্পানী, এসবিসিএল স্কুল এন্ড কলেজ, এসবিসিএল ডায়াগনস্টিক সেন্টার ও হাসপাতাল, এসবিসিএল কম্পিউটার ইন্সস্টিটিউট প্রকল্প সমূহ বাস্তবায়ন করা।</p>', 'ok', 'OK', '2023-04-09 04:18:08', 0),
(232, 'কর্মসংস্থান সৃষ্টি', '26759', 'custom', 211, '<table border=\"1\" cellpadding=\"1\" cellspacing=\"1\" style=\"width:100%\">\r\n	<tbody>\r\n		<tr>\r\n			<td colspan=\"5\" style=\"text-align:center\"><strong>প্রাথমিক ও কেন্দ্রীয় সমিতিসহ মোট ১৭ (সতেরো) টি সমবায় সমিতির ৪৬ (৩) বিধিমতে সরাসরি কর্মসংস্থান সৃষ্টি</strong></td>\r\n		</tr>\r\n		<tr>\r\n			<td rowspan=\"2\" style=\"text-align:center\"><strong>অর্থবছর</strong></td>\r\n			<td rowspan=\"2\" style=\"text-align:center\"><strong>বিগত বছর</strong></td>\r\n			<td colspan=\"2\" style=\"text-align:center\"><strong>বর্তমান বছরে</strong></td>\r\n			<td rowspan=\"2\" style=\"text-align:center\"><strong>মোট কর্মসংস্থান</strong></td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"text-align:center\"><strong>নিয়োগ</strong></td>\r\n			<td style=\"text-align:center\"><strong>চাকুরিচ্যুত</strong></td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"text-align:center\">২০১৯-২০২০</td>\r\n			<td style=\"text-align:center\">১৬৬</td>\r\n			<td style=\"text-align:center\">৪১</td>\r\n			<td style=\"text-align:center\">-</td>\r\n			<td style=\"text-align:center\">২০৭</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"text-align:center\">২০১৮-২০১৯</td>\r\n			<td style=\"text-align:center\">১২০</td>\r\n			<td style=\"text-align:center\">৪৬</td>\r\n			<td style=\"text-align:center\">-</td>\r\n			<td style=\"text-align:center\">১৬৬</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n\r\n<p>&nbsp;</p>', 'ok', 'OK', '2023-04-09 04:29:06', 0),
(233, 'উদ্যোক্তা তৈরি', '13149', 'custom', 211, '<p>সমিতির বিনিয়োগ প্রদানের মাধ্যমে স্বাবলম্বী বা উদ্যোক্তা সদস্য</p>\n\n<p>মৎস্য চাষ প্রকল্প : মোঃ সেলিম খান, পিতা- আলিফ খান, কড়ৈইতলী, ফরিদগঞ্জ ২০১১ খ্রিঃ ১৫০০০০০ টাকা বিনিয়োগ গ্রহণ করে।</p>\n\n<p>মুরগীর ফার্ম : আতিক উল্ল্যাহ, পিতা-নুরুল ইসলাম, রুদ্রগাও, ফরিদগঞ্জ, ২০০৭ খ্রিৎ ৮৭৫০০০টাকা।</p>\n\n<p>মুড়ী উৎপাদন : আবু সাহেদ সরকার, পিতা- মৃত মোজাফুর আহম্মেদ মিয়া, নয়াহাট, ফরিদগঞ্জ ১৫০০০০০ টাকা ২০১১ খ্রিঃ বিনিয়োগ গ্রহন করে।</p>\n\n<p>জুতা তৈরীর কারখানা : আবু সাহেদ সরকার, পিতা- মৃত মোজাফুর আহম্মেদ মিয়া, নয়াহাট, ফরিদগঞ্জ ১৫০০০০০ টাকা ২০১১ খ্রিঃ বিনিয়োগ গ্রহন করে।</p>\n\n<p>মুরগীর ডিম উৎপাদন : ইকবাল বিল বাশার, মৃতঃ আবুল বাসার, হাজীগঞ্জ, চাঁদপুর ২০১১ খ্রিঃ ১৫০০০০০ টাকা বিনিয়োগ গ্রহণ করে।</p>\n\n<p>এভাবে সমিতি থেকে বিভিন্ন ট্রেডে বিনিয়োগ গ্রহণ করে............জন উদ্যোক্তা তৈরি হইয়াছে।</p>', 'ok', 'OK', '2022-01-19 05:42:16', 0),
(234, 'কিস্তিতে পণ্য বিক্রয়', '53227', 'custom', 211, '<p>সমিতির সদস্যগণের মধ্যে গৃহনির্মাণ ও গৃহসামগ্রী কিস্তিতে বিক্রয় করা হয়। সদস্যগণ তাদের সদস্যপদের বিপরীতে গৃহ নির্মাণের এবং গৃহের প্রয়োজনীয় পণ্য সামগ্রী সমিতির মাধ্যমে ক্রয় করতে পারেন।</p>', 'ok', 'OK', '2022-08-13 12:08:14', 0),
(235, 'স্বনির্ভরতা অর্জন', '11340', 'custom', 211, '<p>সমিতির কর্ম এলাকা প্রশিক্ষণপ্রাপ্ত বা শিক্ষিত বেকার সদস্যদের যেকোনো আয়-বর্ধক কাজে এবং উদ্যোক্তা, পেশাজীবী, গৃহিনী ও বিদ্যমান পেশার পাশাপাশি উৎপাদন কাজে নিয়োজিত হতে আগ্রহী সদস্যদের উৎপাদিত পণ্য/কাজের নমুনা বা পরিকল্পনা দেখে উৎপাদন কাজের জন্য বিনিয়োগ প্রদান করা হয়। এছাড়াও সমিতির কর্মএলাকার ক্ষুদ্র ও মাঝারি ব্যবসায়ী সদস্যগণকে তাদের ব্যবসার মালামাল বা পণ্য ক্রয়ের উদ্দেশ্যে চলতি মূলধন হিসেবে বিনিয়োগ প্রদান করা হয়।</p>', 'ok', 'OK', '2022-08-13 12:08:51', 0),
(236, 'দারিদ্র বিমোচন', '83674', 'custom', 211, '<p>সমিতির কর্ম এলাকার কৃষক বা হত-দরিদ্র বা স্বল্প আয়ের পেশাজীবী সদস্যগনকে তাদের উৎপাদনমূখী, যেমন – হাঁস-মুরগী পালন, গবাদি পশু পালন, মাছ চাষসহ উৎপাদনমূখী বিভিন্ন খামার, কুটির শিল্প ও হস্ত শিল্প ইত্যাদি স্থাপন ও আয়-বর্ধক কাজে বিনিয়োগ প্রদান করে কর্মসংস্থান সৃষ্টির পাশাপাশি দারিদ্র্য বিমোচন করা হয়।</p>', 'ok', 'OK', '2022-08-13 12:09:21', 0),
(237, 'উৎপাদন ও বিপণন', '69032', 'custom', 211, '<p style=\"text-align:justify\">প্রক্রিয়াধীন</p>', 'ok', 'OK', '2022-08-27 11:17:50', 0),
(238, 'সামাজিক কর্মকাণ্ড', '13698', 'custom', 211, '<p style=\"text-align: justify;\">সামাজিক দায়বদ্ধতা পালনের লক্ষ্যে সাধারণ সভার সিদ্ধান্ত অনুযায়ী ২০০৮ সনে &ldquo;সমাজ ও জনকল্যান তহবিল&rdquo; নামক প্রকল্পের কার্যক্রম আরম্ভ করা হয়। কেন্দ্রীয় সমিতি ও ১৬ (ষোল) টি সদস্য সমিতির নীট লাভ হতে সৃষ্ট দাতব্য তহবিল এবং প্রকল্প বিভাগের বাৎসরিক অনুদান উক্ত তহবিলের উৎস। বিভিন্ন জাতীয় দিবস ও সমবায় দিবস পালন, দুর্যোগকালীন সহযোগিতা, বিভিন্ন ধর্মীয় প্রতিষ্ঠান, শিক্ষা প্রতিষ্ঠান, সাংস্কৃতিক ও ধর্মীয় অনুষ্ঠানে আর্থিক অনুদান প্রদান, এতিম-গরীব অথচ মেধাবীদের লেখাপড়া, মৃত ব্যক্তির দাফন, শীতবস্ত্র বিতরণ, চিকিৎসা খাতে সাহায্য, দরিদ্র মেয়ের বিয়ের অনুদান, শিক্ষা বৃত্তি প্রদান, এবং ধর্মীয় উপাসনালয়,রাস্তাঘাট নির্মাণ-মেরামতসহ সমাজ ও জনসাধারণ উপকার হয় এমন কাজে প্রকল্পের তহবিল হতে অনুদান প্রদান করা হয়।&nbsp;<br />\r\nসমাজ ও জনকল্যান তহবিল হতে ৩০/০৬/২০২২ পর্যন্ত বিভিন্ন খাতে ৯৬৯টি আবেদনের বিপরীতে মোট ৯৫ লক্ষ ৪৬ হাজার ৭২৯ টাকা অনুদান বিতরণ করা হয়।</p>', 'ok', 'OK', '2022-08-27 04:32:01', 0),
(239, 'শিক্ষিত বেকার কো-অপারেটিভ লিমিটেড', '66017', 'custom', 212, '<table border=\"1\" cellpadding=\"1\" cellspacing=\"1\" style=\"width:100%\">\r\n	<tbody>\r\n		<tr>\r\n			<td colspan=\"4\" style=\"text-align: center;\"><strong>শিক্ষিত বেকার কেন্দ্রীয় সঞ্চয় ও ঋণদান সমবায় সমিতি লিমিটেড</strong>\r\n			<div>(নিবন্ধন নম্বর-১১২(চট্ট), তারিখ- ২৭.০১.২০১৫ ইং)</div>\r\n\r\n			<div>(প্রাথমিক সদস্য সমিতি ১৬ টি)</div>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"text-align: center;\"><strong>সদস্য নম্বর</strong></td>\r\n			<td style=\"text-align: center;\"><strong>সদস্য সমিতির নাম</strong></td>\r\n			<td style=\"text-align: center;\"><strong>নিবন্ধন নম্বর</strong></td>\r\n			<td style=\"text-align: center;\"><strong>তারিখ</strong></td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"text-align: center;\">০১</td>\r\n			<td style=\"text-align: center;\">শিক্ষিত বেকার সঞ্চয় ও ঋণদান সমবায় সমিতি লিমিটেড</td>\r\n			<td>নং- ০১/চাঁদ/১২ ইং<br />\r\n			সংশোধিতঃ নং-০১(৯০)চাঁদ/১৫ ইং</td>\r\n			<td style=\"text-align: center;\">০১.০৭.২০১২ ইং - ২৮.০৭.২০১৫ ইং</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"text-align: center;\">০৪</td>\r\n			<td style=\"text-align: center;\">পাটওয়ারী বাজার শিক্ষিত বেকার সঞ্চয় ও ঋণদান সমবায় সমিতি লিমিটেড</td>\r\n			<td>নং- ০২/চাঁদ/১২ ইং<br />\r\n			সংশোধিতঃ নং-০২(৮৩)চাঁদ/১৫ ইং</td>\r\n			<td style=\"text-align: center;\">০১.০৭.২০১২ ইং - ২৭.০৭.২০১৫ ইং</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"text-align: center;\">০৬</td>\r\n			<td style=\"text-align: center;\">বাঘড়া শিক্ষিত বেকার সঞ্চয় ও ঋণদান সমবায় সমিতি লিমিটেড</td>\r\n			<td>নং- ০৩/চাঁদ/১২ ইং<br />\r\n			সংশোধিতঃ নং-০৩(৮৪)চাঁদ/১৫ ইং</td>\r\n			<td style=\"text-align: center;\">০২.০৭.২০১২ ইং - ২৭.০৭.২০১৫ ইং</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"text-align: center;\">০৫</td>\r\n			<td style=\"text-align: center;\">টোরা মুন্সির হাট শিক্ষিত বেকার সঞ্চয় ও ঋণদান সমবায় সমিতি লিমিটেড</td>\r\n			<td>নং-০৪/চাঁদ/১২ ইং<br />\r\n			সংশোধিতঃ নং-০৪(৮৫)চাঁদ/১৫ ইং</td>\r\n			<td style=\"text-align: center;\">০২.০৭.২০১২ ইং - ২৭.০৭.২০১৫ ইং</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"text-align: center;\">১৩</td>\r\n			<td style=\"text-align: center;\">রূপসা শিক্ষিত বেকার সঞ্চয় ও ঋণদান সমবায় সমিতি লিমিটেড</td>\r\n			<td>নং-০৫/চাঁদ/১২ ইং<br />\r\n			সংশোধিতঃ নং-০৫(৮৬)/চাঁদ/১৫ ইং</td>\r\n			<td style=\"text-align: center;\">০৩.০৭.২০১২ ইং - ২৭.০৭.২০১৫ ইং</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"text-align: center;\">০৮</td>\r\n			<td style=\"text-align: center;\">ফরিদগঞ্জ শিক্ষিত বেকার সঞ্চয় ও ঋণদান সমবায় সমিতি লিমিটেড</td>\r\n			<td>নং-০৬/চাঁদ/১২ ইং<br />\r\n			সংশোধিতঃ নং-০৬(৮৭)/চাঁদ/১৫ ইং</td>\r\n			<td style=\"text-align: center;\">০৩.০৭.২০১২ ইং - ২৭.০৭.২০১৫ ইং</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"text-align: center;\">১১</td>\r\n			<td style=\"text-align: center;\">নয়াহাট শিক্ষিত বেকার সঞ্চয় ও ঋণদান সমবায় সমিতি লিমিটেড</td>\r\n			<td>নং-০৭/চাঁদ/১২ ইং<br />\r\n			সংশোধিতঃ নং-০৭(৮৮)/চাঁদ/১৫ ইং</td>\r\n			<td style=\"text-align: center;\">০৪.০৭.২০১২ ইং - ২৮.০৭.২০১৫ ইং</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"text-align: center;\">০৩</td>\r\n			<td style=\"text-align: center;\">চাঁদপুর শিক্ষিত বেকার সঞ্চয় ও ঋণদান সমবায় সমিতি লিমিটেড</td>\r\n			<td>নং-০৮/চাঁদ/১২ ইং<br />\r\n			সংশোধিতঃ নং-০৮(৮৯)/চাঁদ/১৫ ইং</td>\r\n			<td style=\"text-align: center;\">০৪.০৭.২০১২ ইং - ২৮.০৭.২০১৫ ইং</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"text-align: center;\">১৪</td>\r\n			<td style=\"text-align: center;\">মহামায়া শিক্ষিত বেকার সঞ্চয় ও ঋণদান সমবায় সমিতি লিমিটেড</td>\r\n			<td>নং- ০৯/চাঁদ/১২ ইং<br />\r\n			সংশোধিতঃ নং-০৯(৯৭)/চাঁদ/১৫ ইং</td>\r\n			<td style=\"text-align: center;\">০৫.০৭.২০১২ ইং - ২৯.০৭.২০১৫ ইং</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"text-align: center;\">০৭</td>\r\n			<td style=\"text-align: center;\">হাজীগঞ্জ শিক্ষিত বেকার সঞ্চয় ও ঋণদান সমবায় সমিতি লিমিটেড</td>\r\n			<td>নং-১০/চাঁদ/১২ ইং&nbsp;<br />\r\n			সংশোধিতঃ নং-১০(৯৬)/চাঁদ/১৫ ইং</td>\r\n			<td style=\"text-align: center;\">০৫.০৭.২০১২ ইং - ২৯.০৭.২০১৫ ইং</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"text-align: center;\">১২</td>\r\n			<td style=\"text-align: center;\">কচুয়া শিক্ষিত বেকার সঞ্চয় ও ঋণদান সমবায় সমিতি লিমিটেড</td>\r\n			<td>নং -১১/চাঁদ/১২ ইং<br />\r\n			সংশোধিতঃ নং-১১(৯৩)/চাঁদ/১৫ ইং</td>\r\n			<td style=\"text-align: center;\">০৮.০৭.২০১২ ইং - ২৮.০৭.২০১৫ ইং</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"text-align: center;\">০৯</td>\r\n			<td style=\"text-align: center;\">মতলব শিক্ষিত বেকার সঞ্চয় ও ঋণদান সমবায় সমিতি লিমিটেড</td>\r\n			<td>নং- ১২/চাঁদ/১২ ইং<br />\r\n			সংশোধিতঃ নং-১২(৯৪)/চাঁদ/১৫ ইং</td>\r\n			<td style=\"text-align: center;\">০৮.০৭.২০১২ ইং - ২৮.০৭.২০১৫ ইং</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"text-align: center;\">১০</td>\r\n			<td style=\"text-align: center;\">শাহরাস্তি শিক্ষিত বেকার সঞ্চয় ও ঋণদান সমবায় সমিতি লিমিটেড</td>\r\n			<td>নং-১৩/চাঁদ/১২ ইং<br />\r\n			সংশোধিতঃ নং-১৩(৯৫)/চাঁদ/১৫ ইং</td>\r\n			<td style=\"text-align: center;\">০৯.০৭.২০১২ ইং - ২৯.০৭.২০১৫ ইং</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"text-align: center;\">১৫</td>\r\n			<td style=\"text-align: center;\">গৃদকালিন্দিয়া শিক্ষিত বেকার সঞ্চয় ও ঋণদান সমবায় সমিতি লিমিটেড</td>\r\n			<td>নং-১৪/চাঁদ/১২ ইং<br />\r\n			সংশোধিতঃ নং-১৪(৯২)/চাঁদ/১৫ ইং</td>\r\n			<td style=\"text-align: center;\">০৯.০৭.২০১২ ইং - ২৮.০৭.২০১৫ ইং</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"text-align: center;\">০২</td>\r\n			<td style=\"text-align: center;\">ওয়ারলেছ বাজার শিক্ষিত বেকার সঞ্চয় ও ঋণদান সমবায় সমিতি লিমিটেড</td>\r\n			<td>নং-১৫/চাঁদ/১২ ইং<br />\r\n			সংশোধিতঃ নং-১৫(৯১)/চাঁদ/১৫ ইং</td>\r\n			<td style=\"text-align: center;\">০৯.০৭.২০১২ ইং - ২৮.০৭.২০১৫ ইং</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"text-align: center;\">১৬</td>\r\n			<td style=\"text-align: center;\">চান্দ্রা শিক্ষিত বেকার যুব বহুমূখী সমবায় সমিতি লি.</td>\r\n			<td>নং- ৫২৭/ চাঁদ/২০০১ ইং<br />\r\n			সর্বশেষ সংশোধিতঃ নং-৫২৭/চট্টো/০৫</td>\r\n			<td style=\"text-align: center;\">১৭.০৬.২০০১ ইং - ২৯.১১.২০১৫ ইং</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n\r\n<p>&nbsp;</p>', 'ok', 'ok', '2023-04-09 04:56:52', 0),
(243, 'কর্মসংস্থান ও দারিদ্র্য বিমোচন প্রকল্প', '61021', 'custom', 212, '<p style=\"text-align: justify;\">বার্ষিক সাধারণ সভার সিদ্ধান্তক্রমে আবেদনের প্রেক্ষিতে, &ldquo;কর্মসংস্থান ও দারিদ্র্য বিমোচন প্রকল্প&rdquo; সারপত্র জেলা সমবায় অফিসার, চাঁদপুর কর্তৃক স্বারক নং ৪র্থ-২২৭/১২(১৪তম অংশ) &ndash; ৮৮৭/৩, তারিখ ১২.০৮.২০১৪ মূলে অনুমোদিত হয়। কর্মসংস্থান সৃষ্টি ও দারিদ্র্য বিমোচনের মাধ্যমে স্বনির্ভরতা অর্জন, আর্থ-সামাজিক উন্নয়ন, সমিতির কার্যক্রম সম্প্রসারণ করা প্রকল্পের উদ্দেশ্য। এই প্রকল্পের মূল কাজ হচ্ছে প্রকল্পের আওতায় সমিতির কর্ম-এলাকার বেকার শিক্ষিত পুরুষ ও মহিলাদেরকে সরাসরি চাকরির মাধ্যমে কর্মসংস্থানের সুযোগ সৃষ্টি করা এবং বেকার যুবক ও যুব মহিলাদের বিভিন্ন লাভজনক খাতে ঋণ দিয়ে বিকল্প কর্মসংস্থান সৃষ্টি করা, উদ্যোক্তা সৃষ্টি করা, দরিদ্র ও অসহায় লোকদের স্বাবলম্বী করা এবং উৎপাদনমুখী কাজে ঋণপ্রদান করা। ১৪ টি প্রাথমিক সমিতির মাধ্যমে &ldquo;কর্মসংস্থান ও দারিদ্র্য বিমোচন প্রকল্প&rdquo; টি বাস্তবায়নের নিমিত্তে ২০১৪ খ্রিঃ হতে কার্যক্রম চলমান। ৩০ জুন, ২০২২ খ্রিঃ পর্যন্ত উক্ত প্রকল্পে সরাসরি কর্মসংস্থান সৃষ্টি পুরুষ ১৭৫ জন, মহিলা ৪০ জন, সর্বমোট ২১৫ জন। উদ্যোক্তাদের ঋণদানের মাধ্যমে প্রায় ৫০০ জনের কর্মসংস্থান সৃষ্টি হয়।</p>', 'ok', 'OK', '2022-10-22 09:31:14', 0),
(245, 'এসবিসিএল ডায়াগনস্টিক সেন্টার', '64857', 'custom', 212, '<p>প্রক্রিয়াধীন</p>', 'ok', 'OK', '2022-10-08 03:34:22', 0),
