(250, 'বাজেট বাস্তবায়নের হার (বছর ভিত্তিক)', '54149', 'custom', 213, '<table border=\"1\" cellpadding=\"1\" cellspacing=\"1\" style=\"width:100%\">\r\n	<tbody>\r\n		<tr>\r\n			<td style=\"text-align:center\"><strong>অর্থবছর</strong></td>\r\n			<td style=\"text-align:center\"><strong>বাজেট অনুমোদনের বার্ষিক সাধারণ সভা নং ও তারিখ</strong></td>\r\n			<td style=\"text-align:center\"><strong>নিবন্ধক কর্তৃক অনুমোদনের তারিখ ও স্মারক নং</strong></td>\r\n			<td style=\"text-align:center\"><strong>বাজেট বাস্তবায়নের হার</strong></td>\r\n			<td style=\"text-align:center\"><strong>মন্তব্য</strong></td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"text-align:center\">২০২২-২০২৩</td>\r\n			<td style=\"text-align:center\">২৩তম, ১১.০২.২০২৩ খ্রিঃ</td>\r\n			<td style=\"text-align:center\">জেলা সমবায় অফিসার, চাঁদপুর এর ১৯.০৬.২০২২ তারিখ ৪৫৯ নং স্মারক মূলে।</td>\r\n			<td style=\"text-align:center\">&nbsp;</td>\r\n			<td style=\"text-align:center\">&nbsp;</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"text-align:center\">২০২১-২০২২</td>\r\n			<td style=\"text-align:center\">২২তম, ০৫.০২.২০২২ খ্রিঃ</td>\r\n			<td style=\"text-align:center\">জেলা সমবায় অফিসার, চাঁদপুর এর ২০.০৩.২০২২ তারিখ ১৭৬ নং স্মারক মূলে।</td>\r\n			<td style=\"text-align:center\">&nbsp;</td>\r\n			<td style=\"text-align:center\">&nbsp;</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"text-align:center\">২০২০-২০২১</td>\r\n			<td style=\"text-align:center\">২১তম, ১২.০২.২০২১ খ্রিঃ</td>\r\n			<td style=\"text-align:center\">জেলা সমবায় অফিসার, চাঁদপুর এর ১৩.০৭.২০২০ তারিখ ৫০৮ নং স্মারক মূলে।</td>\r\n			<td style=\"text-align:center\">&nbsp;</td>\r\n			<td style=\"text-align:center\">&nbsp;</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"text-align:center\">২০১৯-২০২০</td>\r\n			<td style=\"text-align:center\">২০তম</td>\r\n			<td style=\"text-align:center\">জেলা সমবায় অফিসার, চাঁদপুর এর ২২.০৯.২০১৯ তারিখ ৯২৬ নং স্মারক মূলে।</td>\r\n			<td style=\"text-align:center\">&nbsp;</td>\r\n			<td style=\"text-align:center\">&nbsp;</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"text-align:center\">২০১৮-২০১৯</td>\r\n			<td style=\"text-align:center\">১৯তম</td>\r\n			<td style=\"text-align:center\">জেলা সমবায় অফিসার, চাঁদপুর এর ০৮.১০.২০১৮ তারিখ ১৩৬৭ নং স্মারক মূলে।</td>\r\n			<td style=\"text-align:center\">&nbsp;</td>\r\n			<td style=\"text-align:center\">&nbsp;</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"text-align:center\">২০১৭-২০১৮</td>\r\n			<td style=\"text-align:center\">১৮তম</td>\r\n			<td style=\"text-align:center\">-</td>\r\n			<td style=\"text-align:center\">&nbsp;</td>\r\n			<td style=\"text-align:center\">&nbsp;</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"text-align:center\">২০১৬-২০১৭</td>\r\n			<td style=\"text-align:center\">১৭তম, ০৩.০৩.২০১৭ খ্রিঃ</td>\r\n			<td style=\"text-align:center\">জেলা সমবায় অফিসার, চাঁদপুর এর ০৬.০৩.২০১৬ তারিখ ৬৩৯ নং স্মারক মূলে।</td>\r\n			<td style=\"text-align:center\">&nbsp;</td>\r\n			<td style=\"text-align:center\">&nbsp;</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"text-align:center\">২০১৫-২০১৬</td>\r\n			<td style=\"text-align:center\">১৬তম, ২৬.০২.২০১৬ খ্রিঃ</td>\r\n			<td style=\"text-align:center\">-</td>\r\n			<td style=\"text-align:center\">&nbsp;</td>\r\n			<td style=\"text-align:center\">&nbsp;</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"text-align:center\">২০১৪-২০১৫</td>\r\n			<td style=\"text-align:center\">১৫তম, ২২.০৫.২০১৫ খ্রিঃ</td>\r\n			<td style=\"text-align:center\">-</td>\r\n			<td style=\"text-align:center\">&nbsp;</td>\r\n			<td style=\"text-align:center\">&nbsp;</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"text-align:center\">২০১৩-২০১৪</td>\r\n			<td style=\"text-align:center\">১৪তম</td>\r\n			<td style=\"text-align:center\">-</td>\r\n			<td style=\"text-align:center\">&nbsp;</td>\r\n			<td style=\"text-align:center\">&nbsp;</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"text-align:center\">২০১২-২০১৩</td>\r\n			<td style=\"text-align:center\">১৩তম</td>\r\n			<td style=\"text-align:center\">যুগ্ম নিবন্ধক, বিভাগীয় সমবায় দপ্তর, চট্টগ্রাম এর ১৮.০৬.২০১৩ ইং তারিখে ১৩০৪ নং স্মারক মূলে।</td>\r\n			<td style=\"text-align:center\">&nbsp;</td>\r\n			<td style=\"text-align:center\">&nbsp;</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"text-align:center\">২০১১-২০১২</td>\r\n			<td style=\"text-align:center\">১২তম</td>\r\n			<td style=\"text-align:center\">যুগ্ম নিবন্ধক, বিভাগীয় সমবায় দপ্তর, চট্টগ্রাম এর ২৯.০১.১২ তারিখ ২১৫ নং স্মারক মূলে।</td>\r\n			<td style=\"text-align:center\">&nbsp;</td>\r\n			<td style=\"text-align:center\">&nbsp;</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"text-align:center\">২০১০-২০১১</td>\r\n			<td style=\"text-align:center\">১১তম</td>\r\n			<td style=\"text-align:center\">জেলা সমবায় অফিসার, চাঁদপুর এর ১২.১২.২০১০ তারিখ ১৮১৮(৪) নং স্মারক মূলে।</td>\r\n			<td style=\"text-align:center\">&nbsp;</td>\r\n			<td style=\"text-align:center\">&nbsp;</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"text-align:center\">২০০৯-২০১০</td>\r\n			<td style=\"text-align:center\">১০ম</td>\r\n			<td style=\"text-align:center\">জেলা সমবায় অফিসার, চাঁদপুর এর ২৫.১০.২০০৯ তারিখ ১২৮৫(৪) নং স্মারক মূলে।</td>\r\n			<td style=\"text-align:center\">&nbsp;</td>\r\n			<td style=\"text-align:center\">&nbsp;</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"text-align:center\">২০০৮-২০০৯</td>\r\n			<td style=\"text-align:center\">৯ম</td>\r\n			<td style=\"text-align:center\"><span style=\"background-color:rgb(255, 255, 255); color:rgb(51, 51, 51); font-family:sans-serif,arial,verdana,trebuchet ms; font-size:13px\">জেলা সমবায় অফিসার, চাঁদপুর এর ২৭.০৮.২০০৮ তারিখ ১০২০(৪) নং স্মারক মূলে।</span></td>\r\n			<td style=\"text-align:center\">&nbsp;</td>\r\n			<td style=\"text-align:center\">&nbsp;</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"text-align:center\">২০০৭-২০০৮</td>\r\n			<td style=\"text-align:center\">৮ম</td>\r\n			<td style=\"text-align:center\">-</td>\r\n			<td style=\"text-align:center\">&nbsp;</td>\r\n			<td style=\"text-align:center\">&nbsp;</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"text-align:center\">২০০৬-২০০৭</td>\r\n			<td style=\"text-align:center