(259, 'করোনাকালীন সহযোগিতার চিত্র', '84884', 'custom', 214, '<p>১. সমবায়ীদের মাঝে মাস্ক ও সাবান বিতরণ ।<br />\r\n২. সাধারণ মানুষের মাঝে স্বাস্থ্য সুরক্ষা সামগ্রী বিতরণ।<br />\r\n৩. জেলা প্রশাসক চাঁদপুর কর্তৃক গৃহিত&nbsp; &ldquo;ত্রাণ যাবে বাড়ি&rdquo; কর্মসূচীতে অনুদান&nbsp; প্রদান।<br />\r\n৪. কর্মহীন ও অসহায় ২৬০ টি পরিবারের মাঝে ত্রাণ ও নগদ অর্থ বিতরণ।<br />\r\n৫. চাঁদপুর প্রেসক্লাবে অনুদান প্রদান।<br />\r\n৬. সাংবাদিকদের অনুদান প্রদান।<br />\r\n৭. সাংস্কৃতিক কর্মীদের অনুদান প্রদান।<br />\r\n৮. বিদেশ ফেরৎ অসুস্থ সদস্য/সমবায়ীদের মাঝে অনুদান প্রদান।<br />\r\n৯. পরিবারের একমাত্র উপার্জনশীল স্বামী বিদেশে করোনা আক্রান্ত থাকায় দেশে বসবাসকারী স্ত্রী ও পরিবারকে সাহায্য প্রদান।<br />\r\n১০. করোনাকালীন সময়ে সদস্যদের গৃহিত ঋণের আদায়যোগ্য লাভ ম্ওকুফ।<br />\r\n১১.&nbsp;করোনাকালীন স্বাস্থ্য সুরক্ষার জন্য জনসচেতনামূলক লিফলেট বিতরণ।<br />\r\n১২. স্বাস্থ্য সুরক্ষার জন্য বিভিন্ন প্রশাসনিক কর্মকর্তাদের নিকট শুভেচ্ছা স্বারক হিসেবে সুরক্ষা সামগ্রী বিতরণ।</p>', 'ok', 'OK', '2023-04-09 05:10:35', 0),
(260, 'দরিদ্র সন্তানের লেখাপড়ায় আর্থিক সহায়তা', '42288', 'custom', 214, '<p style=\"text-align: justify;\">সমিতির সাধারণ সভার গৃহীত সিদ্ধান্ত মতে &ldquo;সমাজ ও জনকল্যাণ তহবিল প্রকল্প&rdquo; জেলা সমবায় অফিসার, চাঁদপুর কর্তৃক বিগত ০১.০৭.২০০৯ ইং তারিখ ৭৪০/৩নং স্মারক মূলে অনুমোদিত হয়। উক্ত প্রকল্পের মাধ্যমে বিভিন্ন প্রকার সামাজিক কর্মকান্ডের মধ্যে দরিদ্র্য সন্তানদের লেখাপড়ায় আর্থিক সহায়তা প্রদান করা হয়ে থাকে। জুন, ২০২২ পর্যন্ত সমাজ ও জনকল্যান তহবিল হতে দরিদ্র্য সন্তানদের শিক্ষা উপকরণ সহ লেখাপড়ায় ২২,২৭,০০০/- (বাইশ লক্ষ সাতাশ হাজার) টাকা আর্থিক সহায়তা করা হয়েছে।</p>', 'keywords', 'সমিতির সাধারণ সভার গৃহীত সিদ্ধান্ত মতে “সমাজ ও জনকল্যাণ তহবিল প্রকল্প” জেলা সমবায় অফিসার, চাঁদপুর কর্তৃক বিগত ০১.০৭.২০০৯ ইং তারিখ ৭৪০/৩নং স্মারক মূলে অনুমোদিত হয়। উক্ত প্রকল্পের মাধ্যমে বিভিন্ন প্রকার সামাজিক কর্মকান্ডের মধ্যে দরিদ্র্য সন্তানদের লেখাপড়ায় আর্থিক সহায়তা প্রদান করা হয়ে থাকে। জুন, ২০২২ পর্যন্ত সমাজ ও জনকল্যান তহবিল হতে দরিদ্র্য সন্তানদের শিক্ষা উপকরণ সহ লেখাপড়ায় ২২,২৭,০০০/- (বাইশ লক্ষ সাতাশ হাজার) টাকা আর্থিক সহায়তা করা হয়েছে।', '2022-10-12 04:28:13', 0),
(261, 'দরিদ্র কন্যাসন্তানের বিবাহে আর্থিক সহায়তা', '48499', 'custom', 214, '<p style=\"text-align: center;\">সমাজ ও জনকল্যান তহবিল প্রকল্প হতে জুন, ২০২২ পর্যন্ত দরিদ্র কন্যা সন্তানের বিবাহে ৩,৬৬,৭০০/- (তিন লক্ষ ছেষট্টি হাজার সাতশত) টাকা আর্থিক সহায়তা প্রদান করা হয়।</p>\r\n\r\n<p style=\"text-align: center;\"><img alt=\"\" src=\"https://sbcl.coop/assets/uploads/gallery/1665817067_filename.jpg\" style=\"height:190px; width:300px\" />&nbsp;<img alt=\"\" src=\"https://sbcl.coop/assets/uploads/gallery/1665817082_filename.jpg\" style=\"height:190px; width:300px\" /></p>\r\n\r\n<p>&nbsp;</p>', 'keywords', 'দরিদ্র কন্যাসন্তানের বিবাহে আর্থিক সহায়তা', '2022-10-15 07:00:59', 0),
