(264, 'দরিদ্র পরিবারের গৃহনির্মাণে আর্থিক সহায়তা', '80641', 'custom', 214, '<table border=\"1\" cellpadding=\"0\" cellspacing=\"0\">\n <tbody>\n  <tr>\n    <td colspan=\"3\" >\n   <p>প্রাথমিক ও কেন্দ্রীয় সমিতিসহ ১৭ (সতেরো) টি সমিতির সৃষ্ট &lsquo;&lsquo;সমাজ ও জনকল্যান তহবিল&rsquo;&rsquo; প্রকল্প হতে দরিদ্র পরিবারের গৃহ নির্মানে আর্থিক সহায়তা করা হয়।</p>\n   </td>\n  </tr>\n  <tr>\n    <td >\n   <p>অর্থ-বছর</p>\n   </td>\n    <td >\n   <p>দরিদ্র পরিবারের সংখ্যা</p>\n   </td>\n    <td >\n   <p>গৃহ নির্মাণে আর্থিক সহায়তা</p>\n   </td>\n  </tr>\n  <tr>\n    <td >\n   <p>২০২০-২০২১</p>\n   </td>\n    <td >\n   <p>৩ পরিবার</p>\n   </td>\n    <td >\n   <p>১৫,০০০&nbsp; টাকা</p>\n   </td>\n  </tr>\n </tbody>\n</table>', 'ok', 'OK', '2022-02-03 06:58:13', 0),
(265, 'শিক্ষা প্রতিষ্ঠানে আর্থিক সহায়তা', '38129', 'custom', 214, '<p style=\"text-align:justify\">সমিতির সাধারণ সভার গৃহীত সিদ্ধান্ত মতে &ldquo;সমাজ ও জনকল্যাণ তহবিল প্রকল্প&rdquo; জেলা সমবায় অফিসার, চাঁদপুর কর্তৃক বিগত ০১.০৭.২০০৯ ইং তারিখ ৭৪০/৩নং স্মারক মূলে অনুমোদিত হয়। উক্ত প্রকল্পের মাধ্যমে বিভিন্ন প্রকার সামাজিক কর্মকান্ডের মধ্যে দরিদ্র্য সন্তানদের লেখাপড়ায় আর্থিক সহায়তা প্রদান করা হয়ে থাকে। জুন, ২০২২ পর্যন্ত সমাজ ও জনকল্যান তহবিল হতে দরিদ্র্য সন্তানদের শিক্ষা উপকরণ সহ লেখাপড়ায় ২২,২৭,০০০/- (বাইশ লক্ষ সাতাশ হাজার) টাকা আর্থিক সহায়তা করা হয়েছে।</p>\r\n\r\n<p style=\"text-align: center;\"><img alt=\"শিক্ষা প্রতিষ্ঠানে আর্থিক সহায়তা\" src=\"https://sbcl.coop/assets/uploads/gallery/1665817151_filename.jpg\" style=\"height:190px; width:300px\" />&nbsp;<img alt=\"শিক্ষা প্রতিষ্ঠানে আর্থিক সহায়তা\" src=\"https://sbcl.coop/assets/uploads/gallery/1665817162_filename.JPG\" style=\"height:190px; width:300px\" /></p>', 'keywords', 'সমিতির সাধারণ সভার গৃহীত সিদ্ধান্ত মতে “সমাজ ও জনকল্যাণ তহবিল প্রকল্প” জেলা সমবায় অফিসার, চাঁদপুর কর্তৃক বিগত ০১.০৭.২০০৯ ইং তারিখ ৭৪০/৩নং স্মারক মূলে অনুমোদিত হয়। উক্ত প্রকল্পের মাধ্যমে বিভিন্ন প্রকার সামাজিক কর্মকান্ডের মধ্যে দরিদ্র্য সন্তানদের লেখাপড়ায় আর্থিক সহায়তা প্রদান করা হয়ে থাকে। জুন, ২০২২ পর্যন্ত সমাজ ও জনকল্যান তহবিল হতে দরিদ্র্য সন্তানদের শিক্ষা উপকরণ সহ লেখাপড়ায় ২২,২৭,০০০/- (বাইশ লক্ষ সাতাশ হাজার) টাকা আর্থিক সহায়তা করা হয়েছে।', '2022-10-15 07:02:50', 0),
